const sections=[{"id": "report:nested:intro", "title": "Intro", "depth": 2, "path": ["Intro"], "children": [], "queryIds": ["report_model_schematics", "rl_method_contract"], "fragments": [{"kind": "prose", "id": "report:nested:intro:part-0", "value": "## Intro"}, {"kind": "prose", "id": "report:nested:intro:part-1", "value": "We want a compact active flange that keeps the **normal pressing force experienced by the workpiece within ±0.5 N of a 5–50 N target**, including while crossing a **1 mm high, 10 mm wide bump at 100 mm/s**. It should work with fixed flange orientations from **0° to 90°** and interchangeable tool masses **S = 0.1–2 kg**. The assumed moving holder B is 0.6 kg, giving **0.7–2.6 kg total tool-side mass**. Robot-side body A is budgeted separately: 0.4 kg in the simulation inputs, approximately 1.5 kg as the physical payload allowance for the real coil example below. With the selected upper rigid attachment, A follows prescribed robot motion; its mass does not create another simulated dynamic mode. The robot payload and frame flexibility need separate verification.\n\nThe controller may use a multi-axis load cell between B and S, tool position relative to A, an accelerometer mounted on S, known tool weight or a gravity tare, and a causal prediction of robot commands already issued. It receives no bump profile or surface preview. We want understandable native Simulink blocks, a measured performance margin, reasonable spring and damper values, and a practical actuator and sensing recommendation. Any springs must fit within **100 mm combined free length and 100 mm combined maximum installed length**. Removed springs are replaced by rigid connections.\n\nFor the first custom PCB, **the accelerometer and ADC chips together should cost less than €100**. This budget excludes the load cell, instrumentation amplifiers, PCB manufacture and assembly. The control study now uses a budget sensing candidate; the faster scientific-reference results remain separately identified."}]}, {"id": "report:nested:question", "title": "Question", "depth": 2, "path": ["Question"], "children": [], "queryIds": ["report_model_schematics", "rl_method_contract"], "fragments": [{"kind": "prose", "id": "report:nested:question:part-0", "value": "## Question"}, {"kind": "prose", "id": "report:nested:question:part-1", "value": "**How should we design a compact active sanding flange that meets the pressing-force requirement with useful margin, reasonable mechanics and affordable sensing—and does a small learned controller improve that system?**\n\nRobot recentering accepts ±7.5 mm about mid-stroke without a centering penalty; force tracking and physical stops retain their limits.\n\nThe component questions below cover mechanics, actuator/drive, force/position sensing, acceleration sensing, acquisition, fast force control, robot commands, learned control and prototype qualification. Each uses the same **Intro → Question → Results → Recommendation** structure. The learned policies have the same causal input restrictions and physical limits as the existing controller."}]}, {"id": "report:nested:results", "title": "Results", "depth": 2, "path": ["Results"], "children": [{"id": "report:nested:results:mechanics-load-path-springs-and-guides", "title": "Mechanics: load path, springs and guides", "depth": 3, "path": ["Results", "Mechanics: load path, springs and guides"], "children": [{"id": "report:nested:results:mechanics-load-path-springs-and-guides:intro", "title": "Intro", "depth": 4, "path": ["Results", "Mechanics: load path, springs and guides", "Intro"], "children": [], "queryIds": ["selected_settings", "actual_mechanics_tolerance", "lower_spring_search", "lower_series_repeated_reference", "mixed_mechanics_identification", "mixed_static_calibration", "force_position_parts"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:intro:part-1", "value": "The mechanical assembly must preserve a measurable load path while allowing the actuator to correct tool motion quickly. Spring packing, guide friction, structural modes and the partition of moving mass all affect the force controller."}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:question", "title": "Question", "depth": 4, "path": ["Results", "Mechanics: load path, springs and guides", "Question"], "children": [], "queryIds": ["selected_settings", "actual_mechanics_tolerance", "lower_spring_search", "lower_series_repeated_reference", "mixed_mechanics_identification", "mixed_static_calibration", "force_position_parts"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:question:part-1", "value": "Which attachment arrangement and approximate spring/damper values can handle the specified bump across the tool-mass range, fit the spring-only 100 mm limits and remain practical to build?"}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:results", "title": "Results", "depth": 4, "path": ["Results", "Mechanics: load path, springs and guides", "Results"], "children": [{"id": "report:nested:results:mechanics-load-path-springs-and-guides:results:mechanical-model-and-sensor-placement", "title": "Mechanical model and sensor placement", "depth": 5, "path": ["Results", "Mechanics: load path, springs and guides", "Results", "Mechanical model and sensor placement"], "children": [], "queryIds": ["selected_settings", "report_model_schematics"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:mechanical-model-and-sensor-placement:part-0", "value": "##### Mechanical model and sensor placement"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:mechanical-model-and-sensor-placement:part-1", "value": "The robot supplies the slow gross motion. The upper attachment connects the robot boundary R to body A. A short-stroke actuator between A and holder B supplies the fast correction. From B, the mechanical load passes through the lower attachment and then the multi-axis load cell to the sanding tool S, which contacts the workpiece. Either attachment can be compliant or rigid.\n\nThe position sensor measures S relative to A. The accelerometer is mounted on S, beyond the load cell."}, {"kind": "figure", "id": "inertial:acf_mechanism_and_sensors", "title": "Mechanical load path and sensor placement", "caption": "Conceptual layout of the selected candidate. Every lower axial load passes through the cell; S–A position spans the full mechanism. This is not a dimensional drawing.", "queryId": "report_model_schematics", "asset": "figure0"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:mechanical-model-and-sensor-placement:part-2", "value": "An attachment spring is an opposed, guided pair: both springs stay in compression while their difference supplies a signed net force. A damper acts across the same relative motion. A rigid attachment removes that motion while retaining the connection and its reaction force. Zero spring stiffness without a replacement connection would leave a free body, so that is a different physical system.\n\nPositions are positive away from the workpiece. The actuator gap is `u = xA − xB`; actual travel is its configured midpoint plus u. R is the prescribed robot-side boundary. A/B/S masses follow Newton's law. With both attachments compliant:\n\n```text\nq1 = q10 + k1 (xS − xB) + c1 (vS − vB)\nq2 = q20 + k2 (xA − xR) + c2 (vA − vR)\n\nmA aA = Fa − q2 − mA g_axis\nmB aB = q1 − Fa − mB g_axis\nmS aS = Rz − q1 − mS g_axis\n```\n\n`q1` is the lower connection force, `q2` the upper connection force, `Fa` the actuator's net axial force after actual guide friction, and `Rz` the axial component of workpiece reaction. The coil's electromagnetic force is `Kf I`; subtract guide friction to obtain Fa in these motion balances. `g_axis = g cos(theta)` represents gravity along the flange axis. The orientation changes the operating load, rather than changing the mass or stiffness.\n\nFor rigid attachments the model enforces the corresponding constraints and calculates their reaction forces. It does not approximate a rigid connection with an enormous numerical spring. If both attachments are rigid, A follows the robot and B follows S, so:\n\n```text\nRz = Fa + (mB + mS) (g_axis + aS)\n```\n\nThis arrangement still moves: the actuator changes A–B separation. Removing the external springs removes additional compliant joints; it does not lock the actuator at one position.\n\nThe selected candidate makes the **upper attachment rigid** and puts an **opposed spring pair and a parallel damper in the lower attachment**. All of that attachment's load passes through the multi-axis cell before reaching S. A spring or guide that transfers axial load directly to S around the sensing element would invalidate the force reconstruction. The spring/damper joining frame is treated as massless in this model; its real inertia is an important prototype check.\n\nEach recording starts at its own loaded equilibrium for the selected force and orientation. The reference link loads are `q10 = Fref − mS g_axis` and `q20 = Fref − (mA+mB+mS) g_axis`; the starting actuator load is `Fa0 = Fref − (mB+mS) g_axis`. An opposing spring pair's common preload is a separate quantity. The fixed-orientation recordings do not establish the transient behavior of changing force target or rotating a loaded tool."}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:results:contact-model-and-disturbance-severity", "title": "Contact model and disturbance severity", "depth": 5, "path": ["Results", "Mechanics: load path, springs and guides", "Results", "Contact model and disturbance severity"], "children": [], "queryIds": ["bump_motion", "report_model_schematics"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:contact-model-and-disturbance-severity:part-0", "value": "##### Contact model and disturbance severity"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:contact-model-and-disturbance-severity:part-1", "value": "The contact model represents a tool following a prescribed smooth surface while sliding tangentially. For local slope s, the unit normal and tangent in the scanning plane are:\n\n```text\nn = (−s, 1) / sqrt(1+s²)\nt = ( 1, s) / sqrt(1+s²)\nR = N n − mu N t\nN = n · R\n```\n\nN is the normal pressing force we score. The sliding drag is represented by `mu`; the plant may use a specified value, but the controller does not receive it. It measures the lateral force component instead. For positive scanning:\n\n```text\nN  = Rz sqrt(1+s²) / (1−mu s)\nRx = −N (s+mu) / sqrt(1+s²)\nN  = (Rz − s Rx) / sqrt(1+s²)\n```\n\nThe lateral reaction is carried by the guides and robot boundary. The current model includes that force in contact reconstruction but does not simulate lateral guide deflection or robot structural bending.\n\nThe bump is a smooth polynomial over its width. With H=1 mm, transit time T=0.1 s and normalized progress `q=(t−t_bump)/T`, its height is `h=64 H q³(1−q)³` for 0≤q≤1, and zero outside. Height, velocity and acceleration join continuously at entry/exit. This gives a reproducible demanding disturbance without a mathematically instantaneous displacement step.\n\nThe peak downward surface acceleration is **2.4 m/s²**, the peak axial speed is approximately **34.3 mm/s**, and the peak jerk is approximately **384 m/s³**. Thus a 2 kg downstream tool can contribute **4.8 N** of dynamic inertia to the difference between the cell reading and contact reaction. With a 0.1 kg tool the same effect is only **0.24 N**. The entire moving B+S mass also affects actuator effort, independently of how much mass lies beyond the load cell."}, {"kind": "figure", "id": "inertial:bump_motion_and_inertia", "title": "Specified bump motion and required tool-inertia compensation", "caption": "Calculated from the specified surface polynomial; this figure shows required motion and inertial force, rather than a controller qualification.", "queryId": "bump_motion", "asset": "figure1"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:contact-model-and-disturbance-severity:part-2", "value": "Contact is maintained only while its calculated required normal reaction is nonnegative. The first contact loss or travel-stop hit stops the recording and marks it failed. This chosen model does not continue into free flight, hard-stop impact, or re-contact."}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:results:finite-stiffness-joining-mass-and-guides", "title": "Finite stiffness, joining mass and guides", "depth": 5, "path": ["Results", "Mechanics: load path, springs and guides", "Results", "Finite stiffness, joining mass and guides"], "children": [], "queryIds": ["selected_settings", "actual_mechanics_tolerance", "lower_spring_search", "lower_series_repeated_reference", "mixed_mechanics_identification", "mixed_static_calibration", "force_position_parts"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:finite-stiffness-joining-mass-and-guides:part-0", "value": "##### Finite stiffness, joining mass and guides"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:finite-stiffness-joining-mass-and-guides:part-1", "value": "Rigidly fastening the sensor does not make it infinitely stiff. In the stiff lower-connection reference, the specified Mini27 axial stiffness and B=0.6 kg produce a maintained-contact B-side mode near **1.64 kHz**. The selected external spring/damper instead gives a **passive B-stage frequency near 28.9 Hz in maintained contact**, with damping ratio about 0.28. That is the open mechanical frequency; the closed-loop response also contains force control, acquisition, current dynamics and filtering. Its native plant uses **k1=19,746 N/m and c1=60 N·s/m directly**, with a massless joining frame and no independent cell state. It neglects the representative 64 MN/m cell's approximately **0.031% static series-compliance correction**. The stiff no-springs reference retains the finite cell.\n\nA real joining plate between the spring pair and cell introduces another degree of freedom. Illustrative 50–200 g plate masses with a 64 MN/m cell give high modes around **5.7–2.85 kHz**, rather than removing every structural mode. These are analytical estimates, not native force qualification of a built fixture. Keep the joining assembly light and stiff, measure its modes under load, and include any material mode in the identified controller model before accepting the prototype's margin.\n\nPartition the assembled masses by that load path. S inertia reconstruction uses only mass downstream of the sensing element; the inverse's B mass is actuator-side mass above the spring. An intervening frame is a separate mass: at low frequency its inertia loads the spring together with S, but it is not sensed as downstream tool inertia. Split any frame mass out of the nominal holder budget and include its measured dynamics, rather than entering the same total mass into every compensation gain.\n\nA compact crossed-roller guide is a plausible low-friction starting point. THK quotes a rolling friction coefficient of 0.001–0.0025 for its crossed-roller guides. For an explicitly assumed 50–100 N equivalent bearing/preload load, that corresponds to 0.05–0.25 N of rolling drag. The modeled 0.2 N Coulomb term is therefore a reasonable target to investigate, rather than a measured assembled value. Seal drag, preload, contamination and moving cables require their own checks; the 2 N·s/m viscous term and the smooth reversal transition are engineering assumptions. [THK guide specification](https://tech.thk.com/es/products/pdf/en_b00_015.pdf)."}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:results:spring-and-damper-search", "title": "Spring and damper search", "depth": 5, "path": ["Results", "Mechanics: load path, springs and guides", "Results", "Spring and damper search"], "children": [], "queryIds": ["lower_spring_search"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:spring-and-damper-search:part-0", "value": "##### Spring and damper search"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:spring-and-damper-search:part-1", "value": "The lower-compliance search contains **168 native recordings** across PI, filtered PID and inverse-assisted control, using equal clean/seed-1729 pairs at each compared tuning. The net pair stiffnesses are 12.826 and 19.746 N/mm, with 0, 15 and 60 N·s/m damping. No tested plain PI or PID setting meets ±0.5 N on both recordings while also satisfying spring packing. With the causal lower-link inverse, the 19.746 N/mm pair passes with either 15 or 60 N·s/m damping. The selected 60 N·s/m setting gives better mechanical damping and is the setting tested repeatedly and across the broader operating range."}, {"kind": "figure", "id": "inertial:inertial_mechanics_spring_tuning", "title": "Controller, lower spring rate and damper search", "caption": "168 native recordings. Each cell shows the best complete clean/noisy tuning pair within that family, so this is a tuning search rather than an equal-gain comparison. Hatched cells fail spring working range even where force tracking passes; contact-loss cases are not shown as successful low errors.", "queryId": "lower_spring_search", "asset": "figure2"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:spring-and-damper-search:part-2", "value": "The softer 12.826 N/mm pair can meet force tracking with inverse assistance, but its recorded excursions do not fit the selected spring working envelope. Zero external damping is also tested; it does not provide a qualified alternative in this search. Completely removed springs retain rigid connections and the load cell's own finite stiffness, as in the structural reference above. Removing damping does not remove the actuator's modeled guide friction."}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:results:preload-and-early-working-envelope-evidence", "title": "Preload and early working-envelope evidence", "depth": 5, "path": ["Results", "Mechanics: load path, springs and guides", "Results", "Preload and early working-envelope evidence"], "children": [], "queryIds": ["lower_series_repeated_reference"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:preload-and-early-working-envelope-evidence:part-0", "value": "##### Preload and early working-envelope evidence"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:preload-and-early-working-envelope-evidence:part-1", "value": "The repeated cohort admits a common preload interval of approximately **30.38–36.86 N per spring**, and the configured 33.6 N lies inside it. With 18.1 mm nominal spring free length and ±0.49 mm length tolerance, the conservative total free length is **37.18 mm** and total maximum installed length is **30.37 mm**. In the worst repeated trace, individual spring force spans about **5.70–61.50 N** and compression **0.58–6.23 mm**. The parallel damper reaches about **33.2 mm/s**, **1.99 N** and **0.066 W instantaneous dissipation**; the modeled 10 s mean dissipation is only 1.48 mW. Stiction, seal force and frequency-dependent damping still need characterization."}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:results:identified-mechanical-coefficients-and-numerical-refinement", "title": "Identified mechanical coefficients and numerical refinement", "depth": 5, "path": ["Results", "Mechanics: load path, springs and guides", "Results", "Identified mechanical coefficients and numerical refinement"], "children": [], "queryIds": ["selected_settings", "actual_mechanics_tolerance", "lower_spring_search", "lower_series_repeated_reference", "mixed_mechanics_identification", "mixed_static_calibration", "force_position_parts"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:identified-mechanical-coefficients-and-numerical-refinement:part-0", "value": "##### Identified mechanical coefficients and numerical refinement"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:identified-mechanical-coefficients-and-numerical-refinement:part-1", "value": "An additional **18 native recordings** vary the controller's identified stiffness and damping independently by ±20% while holding the actual selected mechanics fixed. Both clean and noisy heavy-tool cases pass all nine combinations; the worst is **0.36166 N**. This establishes tolerance to those particular identification errors. It does not establish the behavior of a physically changed spring or damper, which is a separate test.\n\nSix solver-refinement recordings at 10, 5 and 2.5 µs all pass. The maximum peak-error difference is approximately **11.9 µN** for the noisy trace and **1.1 µN** for the clean trace. Thus the candidate's roughly 0.13 N repeated-test margin is much larger than this measured time-step sensitivity."}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:results:actual-mechanical-tolerance-and-combined-calibration-cases", "title": "Actual mechanical tolerance and combined calibration cases", "depth": 5, "path": ["Results", "Mechanics: load path, springs and guides", "Results", "Actual mechanical tolerance and combined calibration cases"], "children": [], "queryIds": ["selected_settings", "actual_mechanics_tolerance", "lower_spring_search", "lower_series_repeated_reference", "mixed_mechanics_identification", "mixed_static_calibration", "force_position_parts"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:actual-mechanical-tolerance-and-combined-calibration-cases:part-0", "value": "##### Actual mechanical tolerance and combined calibration cases"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:actual-mechanical-tolerance-and-combined-calibration-cases:part-1", "value": "Physical spring and damper tolerance receives a separate test. **72 native recordings** vary actual lower stiffness and damping independently by **±20%**, while the controller continues to use the nominal identified 19,746 N/m and 60 N·s/m. Each of the nine mechanical combinations has eight common cases: the light/heavy tool endpoints, a clean condition and noise seeds 7, 29 and 1729 at 50 N/90° and drag ratio 0.3. All 72 meet the force requirement; the worst is **0.37437 N**, without drive clipping, contact loss or a travel stop. This is physical-parameter variation, rather than merely changing the controller's coefficients.\n\nThe approximate spring target is **20 mm nominal free length per spring**, ±0.49 mm length tolerance, 9.873 N/mm nominal rate, at least the modeled 68.54 N individual force envelope and 3.18 mm cyclic working stroke. Keep the pair guided and use **33.6 N common preload per spring**. The original shorter 18.1 mm geometry leaves insufficient compression room for the softest ±20% specimens at this fixed preload. Increasing the approximate free length to 20 mm changes packing, not the native force dynamics. Analytical rescoring of the same 72 complete histories makes **all 72 packing checks pass**, with no invented additional force simulations.\n\nAcross those physical variations, a shared feasible preload interval is approximately **30.91–38.89 N per spring**. Individual spring force spans **5.65–61.55 N**, compression **0.477–7.790 mm**, and the smallest tolerance-inclusive installed spring length is **11.72 mm**, above the 11.05 mm minimum working length plus clearance. The conservative cyclic-motion bound is at most **1.09 mm**, below the 3.18 mm provision. Combined free spring length is **40.98 mm**; maximum combined installed length is **35.31 mm** across stiffness tolerance. Both remain well below the 100 mm spring-only limits. These are approximate working-envelope targets, not a claim that a specific catalog spring has already been qualified."}, {"kind": "figure", "id": "inertial:inertial_mechanics_v8_actual_tolerance", "title": "Actual spring and damper tolerance with fixed nominal controller", "caption": "72 native force histories, eight per mechanical combination. Force values use every sample. The packing panel is an analytical 20 mm geometry rescore of those histories; it does not add force experiments.", "queryId": "actual_mechanics_tolerance", "asset": "figure3"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:actual-mechanical-tolerance-and-combined-calibration-cases:part-2", "value": "The lower pair shapes relative dynamics and keeps the sensing load path attached; its common internal preload does **not** offload static pressing force to the robot. At 50 N and 90°, the generic 20 N/A, 4 Ω coil still holds 2.5 A and dissipates 25 W. The real coil's holding heat is evaluated separately below.\n\nA separate **six-record combined stress comparison** adds actual stiffness +20% and damping −20% to the heavy simultaneous-calibration corner, using three common noise seeds. With the inverse still using nominal k/c, all three pass but the worst reaches **0.489996 N**, leaving only **0.010004 N** reserve. Changing only the inverse's identified stiffness/damping to the known actual **23,695.2 N/m and 48 N·s/m** lowers the worst to **0.453026 N**, recovering **0.036970 N** and leaving **0.046974 N** reserve. Peak current and voltage rise to 3.0045 A and 21.3319 V, without clipping; packing still passes."}, {"kind": "figure", "id": "inertial:inertial_mechanics_mixed_comparison", "title": "Assembled mechanical identification improves the combined stress corner", "caption": "Three paired seeds at one heavy combined corner, six complete four-second native histories. The bars score all samples and the entry traces show every sample in the displayed window. Known actual k/c are supplied exactly in the second group; this does not establish a residual k/c calibration allowance or a complete combined-tolerance region.", "queryId": "mixed_mechanics_identification", "asset": "figure4"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:actual-mechanical-tolerance-and-combined-calibration-cases:part-3", "value": "This makes assembled mechanical identification part of the prototype recommendation. Measure the spring pair's loaded stiffness and damper response and enter those values in the inverse. It does not justify assuming that identifying k/c also removes unrelated sensor or robot-timing errors.\n\nThe tighter static calibration targets described below are also tested at this same mechanical corner. Three further four-second records preserve the known actual k/c, physical inputs, noise and timing, and halve only the same sixteen static residuals. All pass, with peaks **0.373044, 0.376938 and 0.357305 N**. The worst reserve is **0.123062 N**, compared with 0.046974 N before that calibration refinement. Peak current/voltage are **2.9987 A / 21.9529 V**, without clipping or stops; spring packing still passes. This is a second narrow paired check of the proposed calibration targets, not a full combined mechanical/calibration grid."}, {"kind": "figure", "id": "inertial:inertial_mixed_static_calibration", "title": "Static calibration at the assembled mechanical stress corner", "caption": "Three new four-second histories paired with three reused known-k/c baselines. Every 400,001 native sample determines each metric; the entry detail retains all native samples. Physical and identified k/c are fixed while only sixteen static calibration residuals halve.", "queryId": "mixed_static_calibration", "asset": "figure5"}]}], "queryIds": ["selected_settings", "actual_mechanics_tolerance", "lower_spring_search", "lower_series_repeated_reference", "mixed_mechanics_identification", "mixed_static_calibration", "force_position_parts"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:results:part-0", "value": "#### Results"}]}, {"id": "report:nested:results:mechanics-load-path-springs-and-guides:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Mechanics: load path, springs and guides", "Recommendation"], "children": [], "queryIds": ["selected_settings", "actual_mechanics_tolerance", "lower_spring_search", "lower_series_repeated_reference", "mixed_mechanics_identification", "mixed_static_calibration", "force_position_parts"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:recommendation:part-1", "value": "Use an **upper rigid attachment** and a **lower guided opposed spring pair** with **19.746 N/mm net stiffness**, approximately **9.873 N/mm per spring**, **33.6 N common preload per spring**, and **60 N·s/m parallel damping**. Start around **20 mm free length per spring**, allowing the stated ±0.49 mm tolerance; the conservative combined free length is **40.98 mm**, and the evaluated maximum combined installed length is **35.31 mm**. Provide the modeled individual force and cyclic-travel envelope.\n\nKeep the complete lower axial load through the cell, budget **B = 0.6 kg** separately from **S = 0.1–2 kg**, and identify assembled stiffness/damping for the inverse. Measure guide stiction, cable drag and joining-frame modes. The finite tests support this starting design; the spring-only packing limit does not qualify the whole flange size."}]}], "queryIds": ["selected_settings", "actual_mechanics_tolerance", "lower_spring_search", "lower_series_repeated_reference", "mixed_mechanics_identification", "mixed_static_calibration", "force_position_parts"], "fragments": [{"kind": "prose", "id": "report:nested:results:mechanics-load-path-springs-and-guides:part-0", "value": "### Mechanics: load path, springs and guides"}]}, {"id": "report:nested:results:actuator-and-electrical-drive", "title": "Actuator and electrical drive", "depth": 3, "path": ["Results", "Actuator and electrical drive"], "children": [{"id": "report:nested:results:actuator-and-electrical-drive:intro", "title": "Intro", "depth": 4, "path": ["Results", "Actuator and electrical drive", "Intro"], "children": [], "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "electrical_reference", "coil_parts", "final_electrical", "full_grid_hot_headroom", "native_headroom_exception", "calibrated_hot_headroom", "acceleration_and_drive_parts", "budget_adc_hot_coil", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:intro:part-1", "value": "The actuator supplies both fast correction and continuous pressing effort. Current response, usable voltage, moving inertia, continuous force over stroke and heat must be assessed together."}]}, {"id": "report:nested:results:actuator-and-electrical-drive:question", "title": "Question", "depth": 4, "path": ["Results", "Actuator and electrical drive", "Question"], "children": [], "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "electrical_reference", "coil_parts", "final_electrical", "full_grid_hot_headroom", "native_headroom_exception", "calibrated_hot_headroom", "acceleration_and_drive_parts", "budget_adc_hot_coil", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:question:part-1", "value": "Should the prototype use a voice coil or leadscrew, and what force constant, stroke, current, voltage and thermal capacity must the actuator and driver provide?"}]}, {"id": "report:nested:results:actuator-and-electrical-drive:results", "title": "Results", "depth": 4, "path": ["Results", "Actuator and electrical drive", "Results"], "children": [{"id": "report:nested:results:actuator-and-electrical-drive:results:representative-real-coil-and-current-drive-hardware", "title": "Representative real coil and current-drive hardware", "depth": 5, "path": ["Results", "Actuator and electrical drive", "Results", "Representative real coil and current-drive hardware"], "children": [], "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "electrical_reference", "coil_parts", "final_electrical", "full_grid_hot_headroom", "native_headroom_exception", "calibrated_hot_headroom", "acceleration_and_drive_parts", "budget_adc_hot_coil", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:representative-real-coil-and-current-drive-hardware:part-0", "value": "##### Representative real coil and current-drive hardware"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:representative-real-coil-and-current-drive-hardware:part-1", "value": "The **Moticont LVCM-070-051-01** is a useful real voice-coil reference: 25.4 mm stroke, 24.4 N/A force constant, 6.4 Ω resistance, 4 mH inductance and a 240 g moving coil. Its published continuous force is 64.7 N near the centre, falling to approximately 52 N near the ends in the manufacturer's curve. The stationary body weighs 1.24 kg, so it requires roughly 1.5 kg of robot-side A allowance rather than the generic 0.4 kg baseline. The moving-coil mass fits inside B=0.6 kg, leaving about 360 g for the holder, guides, sensor attachments and cables. [Product specification](https://www.moticont.com/lvcm-070-051-01.htm), [manufacturer drawing and force curve](https://www.moticont.com/pdf/lvcm-070-051-01.pdf).\n\nAt a 50 N horizontal hold this coil needs approximately 2.05 A and dissipates 26.9 W at its nominal resistance. A 39% resistance increase raises the hold voltage from 13.1 V to 18.2 V and coil heat to 37.4 W. That makes hot-coil amplifier output headroom a more meaningful voltage question than simply comparing nominal 24 V and 48 V supplies. The continuous-force curve, thermal mounting, usable position range and actual current response still need checking together.\n\nA linear current amplifier is useful for the first precise-force prototype because it avoids introducing PWM current ripple into the averaged-voltage model. This carries a cooling cost. With 20 N/A and 4 Ω, a 50 N horizontal hold needs 2.5 A: the coil dissipates 25 W, and an idealized 24 V linear output stage dissipates another 35 W. Raising the supply to 48 V raises that driver loss to 95 W at the same operating point. These are electrical heat calculations; actual voltage drops and thermal mounting must be checked against the driver's safe operating area.\n\nA switched amplifier can be more efficient, but its current ripple needs measurement and, where necessary, filtering or a qualified mechanical attenuation path. A current-loop bandwidth number alone does not bound instantaneous force ripple. Keep the bulky driver and cooling on the robot or in its cabinet, rather than counting them inside the 0.6 kg moving holder allowance."}]}, {"id": "report:nested:results:actuator-and-electrical-drive:results:native-actuator-comparisons-and-transmission-sizing", "title": "Native actuator comparisons and transmission sizing", "depth": 5, "path": ["Results", "Actuator and electrical drive", "Results", "Native actuator comparisons and transmission sizing"], "children": [], "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:native-actuator-comparisons-and-transmission-sizing:part-0", "value": "##### Native actuator comparisons and transmission sizing"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:native-actuator-comparisons-and-transmission-sizing:part-1", "value": "A voice coil converts signed current directly into signed force and avoids screw backlash and rotating inertia. It is a strong first-prototype choice, but it needs continuous holding current, adequate cooling, a low-friction guide, calibrated force constant over the used stroke and a clean current regulator. A large catalogue peak force does not establish continuous 50 N sanding performance.\n\nThe lower spring/damper and correct carrier inverse also make a leadscrew dynamically viable. Four equal-condition pairs using the earlier reference sensing chain all pass:"}, {"kind": "table", "id": "report:nested:results:actuator-and-electrical-drive:results:native-actuator-comparisons-and-transmission-sizing:table-1", "title": "Native actuator comparisons and transmission sizing · Actuator and electrical drive", "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "headers": ["Ten-second native recording, one bump", "Voice-coil peak error", "Leadscrew peak error"], "rows": [{"column0": "S=2 kg, 50 N, 90°, clean", "column1": "0.3264 N", "column2": "0.3337 N"}, {"column0": "S=2 kg, 50 N, 90°, seed 1729", "column1": "0.3281 N", "column2": "0.3313 N"}, {"column0": "S=2 kg, 5 N, 0°, seed 1729", "column1": "0.3214 N", "column2": "0.3229 N"}, {"column0": "S=0.1 kg, 50 N, 90°, seed 1729", "column1": "0.0940 N", "column2": "0.2162 N"}], "rightAligned": [false, true, true]}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:native-actuator-comparisons-and-transmission-sizing:part-2", "value": "The coil reaches approximately **2.90 A / 17.48 V** in this cohort, and the screw **4.08 A / 10.04 V**, without clipping. These eight recordings are a bounded actuator comparison, not full-grid qualification of the screw or the final acquisition chain.\n\nThe final combined native diagram receives its own **four matched pairs with the selected actual acquisition graph**, plus one screw refinement. All **nine recordings pass**. These recordings last **four seconds with one bump**, and are separate from the ten-second reference table above."}, {"kind": "table", "id": "report:nested:results:actuator-and-electrical-drive:results:native-actuator-comparisons-and-transmission-sizing:table-2", "title": "Native actuator comparisons and transmission sizing · Actuator and electrical drive", "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "headers": ["Final four-second native recording", "Voice-coil peak error", "Leadscrew peak error"], "rows": [{"column0": "S=2 kg, 50 N, 90°, clean", "column1": "0.293260 N", "column2": "0.301007 N"}, {"column0": "S=2 kg, 50 N, 90°, seed 1729", "column1": "0.283522 N", "column2": "0.292191 N"}, {"column0": "S=2 kg, 5 N, 0°, seed 1729", "column1": "0.274796 N", "column2": "0.282736 N"}, {"column0": "S=0.1 kg, 50 N, 90°, seed 1729", "column1": "0.100459 N", "column2": "0.219436 N"}], "rightAligned": [false, true, true]}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:native-actuator-comparisons-and-transmission-sizing:part-3", "value": "The final coil cases reach **2.8992 A / 18.4449 V**, and the screw **4.1554 A / 10.3831 V**. All avoid clipping, contact loss and travel stops, pass spring packing, and satisfy independent normal/axial force balances within 2.85×10⁻¹⁴ N. The heavy noisy screw repeat at 5 µs changes its peak by only **1.49×10⁻⁸ N**. This is useful native branch acceptance; it remains four operating conditions, rather than the coil's complete grid or combined calibration qualification for the screw."}, {"kind": "figure", "id": "inertial:inertial_final_actuator_peak_errors", "title": "Final matched native voice-coil and leadscrew results", "caption": "Four final-acquisition pairs, all eight base recordings passing. Peaks use every original sample; the ninth recording is the separate 5 µs screw refinement.", "queryId": "final_actuator_comparison", "asset": "figure6"}, {"kind": "figure", "id": "inertial:inertial_final_actuator_heavy_bump", "title": "Final heavy-tool bump with the two actuators", "caption": "Heavy S=2 kg, 50 N, 90°, seed 1729. Display histories are reduced to approximately 1 ms with native global extrema retained; qualification uses every 10 µs sample. Travel is actuator B–A travel, distinct from the measured S–A position.", "queryId": "final_actuator_comparison", "asset": "figure7"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:native-actuator-comparisons-and-transmission-sizing:part-4", "value": "The screw model retains motor current/inductance, shaft friction, lead and rotor inertia. With `ell=lead/(2 pi)`, the reflected rotational inertia is `Jax=Jrot/ell²`. The motor must accelerate that inertia as well as B. For the compliant lower link, its inverse uses **mB+Jax**, and issued robot acceleration contributes a separate correction. It does not treat shaft torque divided by lead as contact force under every accelerating condition.\n\nThe representative motor is a 24 V **maxon RE25 302005**, with Kt≈0.0234 N·m/A, R≈2.32 Ω, rotor inertia 1.08×10⁻⁶ kg·m² and continuous torque approximately 26.3 mN·m. Adding an assumed 0.5×10⁻⁶ kg·m² screw inertia gives **0.624 kg reflected inertia at 10 mm/revolution**. The same assembly gives 2.50 kg at 5 mm/revolution and 6.93 kg at 3 mm/revolution. A smaller lead increases force per ampere but substantially increases the fast inertial load. [Manufacturer motor data](https://www.maxongroup.com/maxon/view/product/302005)."}, {"kind": "figure", "id": "inertial:screw_pitch_inertia_and_heating", "title": "Screw lead, reflected inertia and continuous holding current", "caption": "Analytical sizing for the reference motor and assumed screw inertia. The 90% efficiency curve is a conservative holding calculation, not an efficiency model used to claim a dynamic pass. Motor torque and temperature also limit continuous operation.", "queryId": "screw_pitch_sizing", "asset": "figure8"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:native-actuator-comparisons-and-transmission-sizing:part-5", "value": "At 10 mm/revolution, an ideal 50 N horizontal hold requires **3.40 A and 26.8 W winding heat**, far above the motor's 1.16 A continuous-current rating. Its ideal continuous axial force is only about 16.5 N before transmission losses. Reducing lead to 3 mm/revolution approaches the continuous-current limit, but 90% efficiency leaves only about 49.6 N from the stated torque rating, before friction, while adding nearly 7 kg of reflected inertia. This particular motor is not suitable for the whole requested envelope even though the peak simulations pass.\n\nA larger servo and low-backlash screw could be a credible alternative. At 10 mm/revolution and 90% efficiency, 50 N alone requires roughly **0.088 N·m continuous shaft torque**. A practical design needs additional continuous and transient reserve, low total rotor/screw inertia, an encoder/commutation solution, measured stiction and a carrier inverse calibrated to the actual mechanism. The larger maxon EC-i30 539489 is a static sizing reference with approximately 103 mN·m continuous torque; it is not dynamically qualified here. [Manufacturer motor data](https://www.maxongroup.com/maxon/view/product/539489).\n\nPneumatic or other servo actuators could also work with their own identified dynamics. This study does not qualify their pressure dynamics, valve delay, seal friction or backlash. For the first precise-force prototype, the voice coil provides the most direct implementation of the tested current-to-force controller. The screw results show that the control/mechanical concept is transferable; they do not show that every screw actuator or motor will satisfy it."}]}, {"id": "report:nested:results:actuator-and-electrical-drive:results:voltage-headroom-current-limits-and-continuous-heat", "title": "Voltage headroom, current limits and continuous heat", "depth": 5, "path": ["Results", "Actuator and electrical drive", "Results", "Voltage headroom, current limits and continuous heat"], "children": [], "queryIds": ["electrical_reference", "coil_parts", "final_electrical", "full_grid_hot_headroom", "native_headroom_exception", "calibrated_hot_headroom", "budget_adc_hot_coil", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:voltage-headroom-current-limits-and-continuous-heat:part-0", "value": "##### Voltage headroom, current limits and continuous heat"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:voltage-headroom-current-limits-and-continuous-heat:part-1", "value": "The retained lower-series electrical study contains **92 distinct configurations from 95 durable native runs**, including explicit parity/reference repeats. **80 pass and 12 fail**. Higher generic bus voltage at the configured 100 µs current response leaves the unclipped recordings unchanged, including the native force/current histories. Increasing the peak-current limit from 3 A to 5 A likewise makes no difference where the largest current request remains about 2.99 A. Additional supply or current capacity helps only when it removes a real limit or supports a separately qualified faster current regulator.\n\nForce-constant uncertainty is tested separately. Unknown ±5% changes pass the sampled cases, with approximately 0.428 N worst error. Unknown ±10% causes startup-transient failures up to about 0.927 N; after 50 ms those traces are within approximately 0.348 N. They still fail the report's full-recording requirement. Increasing voltage does not correct that calibration problem. Establish the operating holding current and force constant before starting the qualified disturbance test, and map any meaningful position/temperature dependence.\n\nThe real Moticont winding is more demanding electrically than the generic 4 Ω/3 mH example. All sampled ideal 24, 36 and 48 V cold/hot cases pass with the matched controller gains and inverse force constant. However, at an assumed 100°C resistance rise, its **requested voltage reaches about 27 V**. Ideal 24 V clips briefly; the contact-force effect in those sampled recordings is small. An effective **19–20 V output** from a nominal 24 V linear amplifier fails the four tested hot cases, with worst errors about **5.71 N at 19 V and 2.81 N at 20 V**. The 4–5 V amplifier-loss envelope is an explicit conservative assumption, rather than a measured dropout specification at 24 V.\n\nThe final acquisition candidate receives an initial **16-run electrical check over 15 distinct conditions**, extended by two native records below to **18 runs / 17 distinct conditions**. Its generic 24/48 V references are bitwise equal across all 72 channels. The real cold/hot coil at ideal 36 V passes, and the hot coil with **31 V usable output** is bitwise equal to its ideal 36 V reference for both seeds, without clipping. The actual hot-coil request reaches **28.473 V**, leaving **2.527 V** at that conservative 31 V output envelope. Hot 19 and 20 V outputs fail all four sampled low-headroom conditions, with worst errors **5.716 and 2.882 N**; contact remains closed and each recording completes. Their pre-bump error remains at most 0.151 N, locating the failure in dynamic voltage headroom rather than startup.\n\nThis subset supports 31 V usable bipolar output for the representative real coil; the broader calibrated-mechanics check below raises the selected output requirement to **32 V**. The 4–5 V stage-loss envelope remains an explicit conservative allowance, not a verified TA115 dropout specification. A 48 V supply does not improve the unclipped response at unchanged tuning and increases a linear driver's heat. Voltage demand includes noisy current regulation as well as static IR and back EMF; checking only the 18.23 V hot holding drop would miss the transient requirement."}, {"kind": "figure", "id": "inertial:inertial_final_voltage_headroom", "title": "Real-coil usable voltage, tracking and steady holding heat", "caption": "16 completed native recordings, including one duplicate software parity reference. The heat panel is a separate steady-load calculation from the stated winding resistance and supply, not a thermal simulation.", "queryId": "final_electrical", "asset": "figure9"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:voltage-headroom-current-limits-and-continuous-heat:part-2", "value": "The hot-winding headroom check also covers **all 3,500 nominal grid identities**, using **3,498 sufficient conservative voltage bounds and two directly executed exception identities**. With known Kf=24.4 N/A, Rhot=8.896 Ω, L=4 mH and unchanged 100 µs current response, scale current-domain control by 20/24.4. The generic native regulator permits the exact mapping `Vhot = 1.22 Vgeneric + 2.411803 I − 3.813115 (Icommand − I)`. A triangle bound from each recorded peak proves 31 V sufficient for 3,498 cases. Two conservative bounds exceed it because their separate peaks need not occur together. Their actual hot31V native runs request at most **28.473 V** and pass without clipping; the additional generic reference matches its archived grid identity exactly.\n\nThis closes the conditional finite-grid electrical screen with two extra native runs, rather than claiming 3,500 real-winding simulations. It depends on the identified constant force constant, matched hot R/L compensation, upper-rigid kinematics, normalized controller and the recorded nominal mechanics/sensors. It does not qualify unknown hot force constant, thermal behavior, the full joint-error budget or continuous force over stroke. The complete derivation and exact parameter/waveform audits are in [the headroom evidence](/home/tommie/Projects/actuator-model/acf_simulink/validation/normal_voltage_final_grid_hot_mapping_20260930.md).\n\nA further **pointwise algebraic hot-winding check** uses all native samples of the four tighter-static 30 s histories and three tighter-static known-k/c mixed histories. It preserves their residual Kf identification while uniformly rescaling all current-domain control by 20/24.4. The long cases request at most **29.5915 V**. One mixed case requests **31.1071 V for one 10 µs sample**, so a 31 V envelope does not reproduce every inspected trajectory without clipping. This is not an observed force failure. **32 V usable terminal output** covers all seven checked histories with at least **0.8929 V** reserve. The mapping adds zero real-coil simulations and retains constant identified winding/current-response assumptions.\n\nTherefore specify a **36 V supply with measured usable bipolar output of at least 32 V** if the selected driver can provide it under hot load. Do not assume a 5 V stage loss and still call that envelope sufficient. If the actual amplifier cannot provide the required terminal output, choose a suitable lower-drop driver, revise the winding or qualify a higher supply with its thermal consequences. Increasing voltage beyond the verified unclipped envelope does not improve the selected response.\n\nAt 50 N and 90°, the real coil holds about **2.05 A**, dissipating **26.9 W cold or 37.4 W at the assumed hot resistance**. Representative RMS current is almost the same as the hold current: holding load dominates coil heat. An ideal linear stage at 36 V then dissipates approximately **46.9 W cold or 36.4 W hot**, independently of cabinet/control electronics. The TA115-class amplifier requires an adequate heatsink/airflow and safe-operating-area check at its actual case temperature. Its published 50 W allowance at a 70°C heatsink leaves little reserve above the calculated 46.9 W cold holding loss. Keep the heatsink cooler or select a stage with adequate operating margin; the generic 20 N/A, 4 Ω winding would require 65 W driver dissipation at 36 V. The Moticont drawing states its winding values at 25°C and inductance at 1 kHz; hot resistance, frequency-dependent inductance, force-constant drift and the published continuous-force curve must be considered together. [Driver datasheet](https://trustautomation.com/datasheets/TA115DataSheet.pdf), [coil drawing](https://www.moticont.com/pdf/lvcm-070-051-01.pdf)."}]}, {"id": "report:nested:results:actuator-and-electrical-drive:results:new-current-response-and-voltage-experiments", "title": "New current-response and voltage experiments", "depth": 5, "path": ["Results", "Actuator and electrical drive", "Results", "New current-response and voltage experiments"], "children": [], "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "electrical_reference", "coil_parts", "final_electrical", "full_grid_hot_headroom", "native_headroom_exception", "calibrated_hot_headroom", "acceleration_and_drive_parts", "budget_adc_hot_coil", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:new-current-response-and-voltage-experiments:part-0", "value": "##### New current-response and voltage experiments"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:new-current-response-and-voltage-experiments:part-1", "value": "The unified-controller study adds a matched drive experiment using one fixed, earlier recurrent checkpoint. At the development worst case, **32, 36 and 48 V usable output give the same 0.418728 N learned peak and 0.428618 N baseline peak with the 100 µs current-response tuning**. Raising voltage removes a few late clipping samples but does not change the worst bump-entry error. Current-loop response and supply voltage are separate design choices.\n\nChanging the modeled and identified response from **100 to 50 µs** gives a clearer benefit. Across the same **28 development conditions**, both controllers pass at both response settings: **112 complete native recordings and 111,600,112 native samples**. The baseline worst peak improves from **0.428618 to 0.397116 N**; the earlier learned checkpoint improves from **0.418728 to 0.373499 N**. Its peak improves in 26 of 28 pairs; the largest of two regressions is 0.003485 N. Brief voltage-clipping samples increase from 104 to 27,176 across its 28 recordings at 32 V, while no current-limit sample occurs. Every recording still passes the force requirement."}, {"kind": "figure", "id": "inertial:current_response_28cases", "title": "Measured development benefit of faster current response", "caption": "Matched development cases and fixed earlier checkpoint, with every native sample scored. These use an earlier checkpoint and faster ADXL1002-like sensing. The final budget-policy comparisons below instead use 50 µs current response, a 1.9 kHz sensing envelope and 32 V usable output.", "queryId": "rl_actuator_response", "asset": "figure10"}, {"kind": "figure", "id": "inertial:actuator_limit_peaks", "title": "Voltage and current-loop response in the same development case", "caption": "Twelve complete recordings separate voltage-only changes from faster current tuning. More voltage removes clipping; changing current response reduces the entry transient. The faster 32 V learned waveform was independently replayed in MATLAB.", "queryId": "rl_actuator_response", "asset": "figure11"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:new-current-response-and-voltage-experiments:part-2", "value": "This supports testing a **50 µs current-response option** on the actual hot coil and driver. It does not support buying a higher-voltage supply as a substitute for measuring loop phase and bandwidth. Confirm stability, ripple, usable voltage and heat before promoting the faster tuning; the tested current-response envelope is an assumption about a regulator, not a demonstrated amplifier specification."}]}], "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "electrical_reference", "coil_parts", "final_electrical", "full_grid_hot_headroom", "native_headroom_exception", "calibrated_hot_headroom", "acceleration_and_drive_parts", "budget_adc_hot_coil", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:results:part-0", "value": "#### Results"}]}, {"id": "report:nested:results:actuator-and-electrical-drive:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Actuator and electrical drive", "Recommendation"], "children": [], "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "electrical_reference", "coil_parts", "final_electrical", "full_grid_hot_headroom", "native_headroom_exception", "calibrated_hot_headroom", "acceleration_and_drive_parts", "budget_adc_hot_coil", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:recommendation:part-1", "value": "Use a **guided voice coil** for the first prototype: approximately **20–25 N/A**, **25 mm travel**, and preferably **65–70 N or more continuous force over the used stroke and operating temperature**. The evaluated winding range is roughly **4–6.4 Ω cold resistance** and **3–4 mH inductance**. Provide bipolar current, at least the modeled **3.5 A peak provision**, and a measured **50 µs current-response target for the current budget candidate**; the earlier scientific-reference tests used 100 µs.\n\nStart with a **36 V supply only if the driver provides at least 32 V usable bipolar output under hot load**. The latest seven M08 hot-coil tests request up to 31.738466 V, so actual dropout needs measurement. Size cooling for continuous holding effort, not just the bump. A suitably larger low-backlash screw remains an alternative, but the tested RE25 is thermally undersized; its transient passes do not qualify continuous 50 N sanding."}]}], "queryIds": ["actuator_pair_reference", "screw_pitch_sizing", "final_actuator_comparison", "electrical_reference", "coil_parts", "final_electrical", "full_grid_hot_headroom", "native_headroom_exception", "calibrated_hot_headroom", "acceleration_and_drive_parts", "budget_adc_hot_coil", "rl_actuator_response", "rl_budget_response_limits", "rl_budget_sensing_contract"], "fragments": [{"kind": "prose", "id": "report:nested:results:actuator-and-electrical-drive:part-0", "value": "### Actuator and electrical drive"}]}, {"id": "report:nested:results:force-and-position-measurement", "title": "Force and position measurement", "depth": 3, "path": ["Results", "Force and position measurement"], "children": [{"id": "report:nested:results:force-and-position-measurement:intro", "title": "Intro", "depth": 4, "path": ["Results", "Force and position measurement", "Intro"], "children": [], "queryIds": ["force_position_parts", "selected_settings", "lower_series_force_balance", "joint_budget_plan"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:intro:part-1", "value": "The B–S cell carries the tool’s downstream mass, so its reading contains support and inertia as well as contact loading. Relative position helps estimate motion and surface direction, while multi-axis force distinguishes pressing from sanding drag."}]}, {"id": "report:nested:results:force-and-position-measurement:question", "title": "Question", "depth": 4, "path": ["Results", "Force and position measurement", "Question"], "children": [], "queryIds": ["force_position_parts", "selected_settings", "lower_series_force_balance", "joint_budget_plan"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:question:part-1", "value": "Where should the sensors be mounted, and how can their readings reconstruct the force the workpiece experiences rather than only the force inside the flange?"}]}, {"id": "report:nested:results:force-and-position-measurement:results", "title": "Results", "depth": 4, "path": ["Results", "Force and position measurement", "Results"], "children": [{"id": "report:nested:results:force-and-position-measurement:results:reaction-vector-reconstruction-and-the-surface-normal", "title": "Reaction-vector reconstruction and the surface normal", "depth": 5, "path": ["Results", "Force and position measurement", "Results", "Reaction-vector reconstruction and the surface normal"], "children": [], "queryIds": ["force_position_parts", "selected_settings", "lower_series_force_balance", "joint_budget_plan"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:results:reaction-vector-reconstruction-and-the-surface-normal:part-0", "value": "##### Reaction-vector reconstruction and the surface normal"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:results:reaction-vector-reconstruction-and-the-surface-normal:part-1", "value": "The cell is between B and S, so it carries the entire downstream tool. Its reading includes the forces needed to support and accelerate S. Static tare can remove known gravity; it cannot remove changing acceleration."}, {"kind": "figure", "id": "inertial:acf_force_reconstruction", "title": "Reconstructing normal pressing force from synchronized measurements", "caption": "Force, acceleration and estimated normal must refer to the same effective time and frame. The observer uses measured motion and robot commands already issued.", "queryId": "report_model_schematics", "asset": "figure12"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:results:reaction-vector-reconstruction-and-the-surface-normal:part-2", "value": "An accelerometer measures **specific acceleration**, `f = aS − g_vector`. At rest it reports the support acceleration opposing gravity. With the cell sign defined as positive workpiece reaction, Newton's law gives the exact translational relationship:\n\n```text\nR = Lraw + mS f\n```\n\nWith consistent static gravity tare on both channels, the same reconstruction becomes:\n\n```text\nRhat = Ltared + mS adynamic_measured\nNhat = nhat · Rhat\n```\n\nThis explains why adding an accelerometer is useful. The contact-force estimate comes from two physical measurements and the known downstream mass; it does not need to infer acceleration from the coil's force constant or pretend that the B–S cell directly measures contact force. Taring the cell and then adding the accelerometer's unmodified gravity reading would double-count gravity. Both channels use one consistent convention.\n\nForce and acceleration must describe the same instant and frame. If the cell transfer is `HL` and the acceleration transfer is `Ha`, the reconstructed vector is:\n\n```text\nRhat = HL R + mS (Ha − HL) f\n```\n\nMatched complete filtering and delay cancel the inertia term; equal sample rates alone do not. At S=2 kg and jerk 384 m/s³, 100 µs differential latency can introduce about **0.0768 N** of inertia error. Matching the faster channel to an identified common response is usually preferable to stacking both sensor filters and adding unnecessary delay.\n\nThe normal-direction estimate also needs the measurement's effective timestamp. A delayed reaction vector contains delayed sanding drag; projecting it onto a present normal can produce an apparent normal-force error. The controller can keep a matched direction for measurement reconstruction and a separate causal prediction for its actuator command.\n\nThe controller estimates local normal direction from tool motion without receiving the bump geometry. Relative S–A position constrains gap and velocity, measured S acceleration supplies the fast motion information, and the issued-command robot predictor supplies the expected A motion. A small position-corrected velocity observer provides the estimate; dividing normal tool velocity by tangential scan velocity gives local slope under the model's maintained-contact assumption. The known actual surface trajectory remains a plant input and a validation reference only."}]}, {"id": "report:nested:results:force-and-position-measurement:results:component-references-range-and-calibrated-accuracy", "title": "Component references, range and calibrated accuracy", "depth": 5, "path": ["Results", "Force and position measurement", "Results", "Component references, range and calibrated accuracy"], "children": [], "queryIds": ["force_position_parts", "selected_settings", "lower_series_force_balance", "joint_budget_plan"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:results:component-references-range-and-calibrated-accuracy:part-0", "value": "##### Component references, range and calibrated accuracy"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:results:component-references-range-and-calibrated-accuracy:part-1", "value": "These parts ground the engineering assumptions. They are representative prototype choices rather than a purchasing list or a claim that catalog values prove the assembled force accuracy."}, {"kind": "table", "id": "report:nested:results:force-and-position-measurement:results:component-references-range-and-calibrated-accuracy:table-1", "title": "Component references, range and calibrated accuracy · Force and position measurement", "queryIds": ["force_position_parts", "selected_settings", "lower_series_force_balance", "joint_budget_plan"], "headers": ["Component class", "Representative example", "Useful published properties", "What still needs verification"], "rows": [{"column0": "Compact multi-axis cell", "column1": "ATI Mini27 Titanium SI-80-4", "column2": "±80 N transverse, ±160 N axial; effective resolution 0.03/0.06 N; 33.4 g; calculated axial stiffness 64 MN/m", "column3": "Combined-load residual calibration, temperature drift, loaded mechanical response and complete channel timing"}, {"column0": "Higher-stiffness cell", "column1": "ATI Nano25 SI-125-3", "column2": "±125/±500 N; effective resolution about 0.021/0.0625 N; axial stiffness 110 MN/m", "column3": "Broad axial range does not itself improve accuracy; calibration and mounted response remain necessary"}, {"column0": "S–A position", "column1": "Protected Renishaw TONiC with RELM scale", "column2": "0.1 µm counter interface is available; certified scale accuracy approximately ±1 µm at 20°C", "column3": "Bracket deflection, dust protection, magnetic reference/limit behavior, encoder latency and lost-count detection"}, {"column0": "Low-noise current drive", "column1": "Trust Automation TA115 class", "column2": "24–48 V, current mode, published 5 kHz bandwidth into 2.5 mH, forced-air cooling", "column3": "Actual 3–4 mH hot-coil response, output headroom, residual current noise and thermal safe operating area"}], "rightAligned": [false, false, false, false]}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:results:component-references-range-and-calibrated-accuracy:part-2", "value": "Sources: [ATI Mini27](https://www.ati-ia.com/products/ft/ft_models.aspx?id=Mini27+Titanium), [ATI Nano25](https://www.ati-ia.com/products/ft/ft_models.aspx?id=Nano25), [TONiC/RELM documentation](https://www.renishaw.com/media/pdf/en/fa9b5d5f3056478c8031f7c3e8091102.pdf), [TA115 datasheet](https://trustautomation.com/datasheets/TA115DataSheet.pdf).\n\nThe load cell must accommodate **raw force before gravity tare**. A 2 kg tool contributes up to 19.6 N laterally at a 90° orientation; sanding drag and sloped contact add to that load. A tare changes the reported zero, not hardware capacity. Moments and combined-axis ratings also need checking for the real tool's lever arm.\n\nPublished force resolution is not calibrated accuracy. Current Mini27 factory accuracy is stated as 0.75–1.25% of full scale, depending on axis: that does not establish a 0.05–0.1 N residual. The assembled system needs independent known-load checks after any offset, gain, axis-matrix and temperature corrections. Sensor calibration limits belong beside the control results, rather than being hidden inside a low-noise assumption. [Current manufacturer specification](https://ati.novanta.com/product/mini27-titanium-force-torque-sensor/)."}]}], "queryIds": ["force_position_parts", "selected_settings", "lower_series_force_balance", "joint_budget_plan"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:results:part-0", "value": "#### Results"}]}, {"id": "report:nested:results:force-and-position-measurement:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Force and position measurement", "Recommendation"], "children": [], "queryIds": ["force_position_parts", "selected_settings", "lower_series_force_balance", "joint_budget_plan"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:force-and-position-measurement:recommendation:part-1", "value": "Use a **multi-axis load cell in the complete B–S load path**, with all S mass beyond it. Measure **S relative to A** with a protected position sensor and synchronized timestamp. A load cell needs capacity for raw gravity, sanding drag and moments before tare.\n\nReconstruct the reaction vector from the consistently tared load and measured S inertia, then project onto the estimated surface normal at the same effective time. Target **±0.01 N residual force zero per used axis**, **±0.05% force gain/cross-axis residuals**, **±0.05° frame alignment**, approximately **1 µm reference-conditioned position noise**, and **±0.05% position-scale residual**. These are assembled post-calibration targets; catalog resolution alone does not establish them."}]}], "queryIds": ["force_position_parts", "selected_settings", "lower_series_force_balance", "joint_budget_plan"], "fragments": [{"kind": "prose", "id": "report:nested:results:force-and-position-measurement:part-0", "value": "### Force and position measurement"}]}, {"id": "report:nested:results:acceleration-measurement", "title": "Acceleration measurement", "depth": 3, "path": ["Results", "Acceleration measurement"], "children": [{"id": "report:nested:results:acceleration-measurement:intro", "title": "Intro", "depth": 4, "path": ["Results", "Acceleration measurement", "Intro"], "children": [], "queryIds": ["acceleration_and_drive_parts", "budget_accelerometer_screen", "budget_accelerometer_parts", "budget_accelerometer_stress", "budget_dynamic_matching", "joint_budget_plan", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:intro:part-1", "value": "Acceleration measured directly on S supplies the dynamic-inertia correction. Lower sensor cost is useful only if noise, complete response, bias and synchronization retain the required force margin."}]}, {"id": "report:nested:results:acceleration-measurement:question", "title": "Question", "depth": 4, "path": ["Results", "Acceleration measurement", "Question"], "children": [], "queryIds": ["acceleration_and_drive_parts", "budget_accelerometer_screen", "budget_accelerometer_parts", "budget_accelerometer_stress", "budget_dynamic_matching", "joint_budget_plan", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:question:part-1", "value": "Can a cheaper accelerometer replace the fast reference sensor without materially reducing force margin, and what resolution, noise, bias and timing must the complete acceleration chain achieve?"}]}, {"id": "report:nested:results:acceleration-measurement:results", "title": "Results", "depth": 4, "path": ["Results", "Acceleration measurement", "Results"], "children": [{"id": "report:nested:results:acceleration-measurement:results:reference-sensor-specific-acceleration-and-acquisition-budgets", "title": "Reference sensor, specific acceleration and acquisition budgets", "depth": 5, "path": ["Results", "Acceleration measurement", "Results", "Reference sensor, specific acceleration and acquisition budgets"], "children": [], "queryIds": ["acceleration_and_drive_parts", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:reference-sensor-specific-acceleration-and-acquisition-budgets:part-0", "value": "##### Reference sensor, specific acceleration and acquisition budgets"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:reference-sensor-specific-acceleration-and-acquisition-budgets:part-1", "value": "The analog **ADXL1002** is the faster acquisition reference: ±50 g and 25 µg/√Hz, with sufficient bandwidth to characterize the load-cell mode. It is single-axis; use two orthogonal units for the present scanning plane and three for a general spatial system. External antialias filtering, offset/gain calibration and matched timing are necessary. Its 11 kHz response specification is not an 11 kHz first-order low-pass corner. [Manufacturer datasheet](https://www.analog.com/media/en/technical-documentation/data-sheets/adxl1001-1002.pdf).\n\nThe original scientific reference uses a simultaneous-sampling **AD7606C-18**, which provides eight 18-bit analog channels. Budget about 0.65 µs conversion provision without oversampling, then include its input filter, readout and computation in the complete timing measurement. A force interface exposing six amplified and conditioned bridge channels plus the two acceleration axes fits one converter for the planar model; the ATI calibration matrix converts those bridge values into force and torque. A full XYZ accelerometer arrangement requires nine channels: use two common-trigger converters, characterize inter-device timing, and latch the position encoder at the same epoch. [ADC datasheet](https://www.analog.com/media/en/technical-documentation/data-sheets/ad7606c-18.pdf), [ATI TWE interface manual](https://www.ati-ia.com/app_content/documents/9620-05-TWE.pdf).\n\nThe ADXL1002's typical response is within 5% out to 4.7 kHz, while its mechanical resonance is around 21 kHz. This makes it a useful reference for a faster acquisition design around the cell's kilohertz modes. An illustrative 10 kΩ/10 nF output pole gives approximately 100 µs, consistent with the datasheet's capacitive-load provisions. At that dominant response, theoretical white acceleration noise is approximately **0.01226 m/s² RMS**. A 40 mV/g sensitivity and the ADC's 0–5 V range give a **0.00468 m/s² quantum**; including ideal quantization gives about 0.01234 m/s² RMS, or **0.0247 N RMS at S=2 kg**.\n\nThat calculation is a starting budget. A single 100 µs RC sampled directly at 10 kHz is not a complete antialias design. Acquire faster, provide adequate out-of-band analog rejection, then decimate to the controller rate; count the complete filter and decimator delay. ATI's DAQ interface includes a published two-pole 5.1 kHz analog filter; a TWE bridge interface needs designed conditioning and filtering instead. Match the installed complex force/acceleration responses over the relevant band, rather than treating either sensor as an ideal first-order part. The AD7606C-18 also contributes input-filter phase: its low-bandwidth mode specifies a typical 25 kHz bandwidth and about 6.8 µs phase delay. The stated acceleration quantum is ideal resolution, rather than the ADC's complete noise or calibrated accuracy.\n\nThe scientific-reference acquisition uses a **100 ksample/s simultaneous raw clock**, matched two-pole approximately 5.1 kHz analog responses, a **50 µs EMA at that raw clock**, and a fresh-sample latch into the **10 kHz force controller**. The native nominal low-frequency delay of the filter pair is **88.92 µs**, before the selected 20 µs acquisition/computation allowance. The accelerometer white-noise budget is approximately **0.014 m/s² RMS** after nominal conditioning, before quantization and final sampling. The ideal acceleration quantum adds about 0.00135 m/s² RMS quantization noise. The 0.014 m/s² conditioned value is a measurement-chain acceptance target, rather than a guaranteed assembled specification: ADC, amplifier and reference noise consume that allowance and must be measured. Exact ATI filter damping, installed sensor response and total timing still need identification; a nominal Butterworth response is an engineering envelope, not a claim about an unspecified manufacturer filter shape. This acquisition graph is used by the scientific-reference qualification below. The dated lower-cost study later in this report separately evaluates replacement converters with their own filters, quantization, noise and timing.\n\nThe three-axis **ADXL354C** remains a useful lower-bandwidth comparison. Its ±8 g noise budget is about 0.0117 m/s² RMS with a 200 µs dominant response, but its internal response around the cell's kilohertz mode needs particular care. It cannot be substituted for a faster sensor by copying only the RMS-noise value. [Manufacturer datasheet](https://www.analog.com/media/en/technical-documentation/data-sheets/adxl354_adxl355.pdf).\n\nThe accelerometer must measure S's rigid-body acceleration near its centre of mass, or rotation and sensor lever arm must be compensated. Mounting on a flexible circuit-board corner can measure board vibration instead. Before selecting range, run the real sander on an instrumented fixture and check clipping, rectified bias and temperature drift; low white-noise density alone does not establish accurate DC force during sanding.\n\nThe ADXL1002 output zero and sensitivity are ratiometric to its supply. The outer ±0.01 m/s² bias stress corresponds to **40.8 µV** at its nominal 40 mV/g output; the selected **±0.005 m/s² target is only 20.4 µV**. With an independent ADC reference, approximately **40.8 µV of uncompensated supply change**, or **8 ppm at 5 V**, uses the tighter zero-error allowance. Use a stable, calibrated sensor/reference ratio or measured supply correction, warm up and tare at operating temperature, and verify drift through a powered sanding run. Initial tare alone does not establish that performance over time. [Accelerometer datasheet](https://www.analog.com/media/en/technical-documentation/data-sheets/adxl1001-1002.pdf).\n\nThe identified downstream mass includes everything on S's side of the sensing element: tool, pad, brackets, sensor carrier, cable portion and fasteners that move with it. The assembly's centre of mass and any rotation must be measured consistently with the force/acceleration frames. The actuator's stationary body still moves with the robot; its mass is robot payload even when it does not contribute to the fast B+S inertia."}]}, {"id": "report:nested:results:acceleration-measurement:results:executed-lower-cost-response-and-calibration-experiments", "title": "Executed lower-cost response and calibration experiments", "depth": 5, "path": ["Results", "Acceleration measurement", "Results", "Executed lower-cost response and calibration experiments"], "children": [], "queryIds": ["budget_accelerometer_screen", "budget_accelerometer_parts", "budget_accelerometer_stress", "budget_dynamic_matching", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:executed-lower-cost-response-and-calibration-experiments:part-0", "value": "##### Executed lower-cost response and calibration experiments"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:executed-lower-cost-response-and-calibration-experiments:part-1", "value": "Two reference single-axis ADXL1002s cost approximately **€129.76** at the observed quantity-one prices. One three-axis **ADXL354C is about €60.44**, while an **ICM-42688-P is about €5.33** and **IIS3DWB about €19.90**. Those are sensor IC comparisons, not complete board costs. The analog ADXL354 still uses the external ADC; the digital candidates have their own conversion. [Component and price review](/home/tommie/Projects/actuator-model/acf_simulink/validation/accelerometer_cost_component_review_20261002.md).\n\nADXL354C's ±8 g setting has an approximately 33.75 µg/√Hz noise-density target and 100 mV/g sensitivity. A centered buffered input into the M08 gives roughly **0.0000140 m/s² per ADC code** and **0.00209 m/s² typical ADC noise**. Its higher sensor noise is larger than the ADC contribution. That resolution is sufficient for investigating the force objective; it does not establish bias, scale, temperature drift or vibration rectification.\n\nThe **published 1.9 kHz overall 3 dB bandwidth is not a complete transfer function**. The ADXL354 has an internal sinc-shaped response and a 2.4 kHz mechanical mode. Current manufacturer documentation does not supply the full coefficients or phase. The following simulations therefore test clearly identified **required matched response envelopes** with the part's noise and range; they do not claim that the part implements a two-pole Butterworth filter. [ADI datasheet](https://www.analog.com/media/en/technical-documentation/data-sheets/adxl354_adxl355.pdf), [response review](/home/tommie/Projects/actuator-model/acf_simulink/validation/budget_accelerometer_response_review_20261002.md)."}, {"kind": "figure", "id": "inertial:budget_accelerometer_envelopes", "title": "Cheaper accelerometer response and noise experiments", "caption": "36 completed native nominal recordings. Analog cases cover both physical endpoints and seeds 7/29; the digital envelope cases cover the heavy endpoint. Counterfactual 3/5.1 kHz ADXL354 bandwidths are retained in the source but excluded from this practical comparison. Extra common delay is known to the estimator and matched across measurements.", "queryId": "budget_accelerometer_screen", "asset": "figure13"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:executed-lower-cost-response-and-calibration-experiments:part-2", "value": "At the existing 100 µs current target, the ADXL354-like 1.9 kHz envelope gives **0.405691 N** worst error with no additional common latency. An extra 50 µs raises it to **0.457041 N**; 100 µs raises it to **0.484946 N**. Noise alone is therefore not the deciding obstacle. These delay increments are sensitivity cases; published bandwidth cannot prove that they bracket the real part's phase.\n\nA separately tested **50 µs current target at ideal 36 V** improves the same envelope to **0.378082 N**, or **0.429852 N** with the extra 50 µs. This changes current-loop bandwidth as well as drive provision. It is not evidence that increasing voltage alone improves an unclipped 100 µs loop. The joint calibration and real-hot-winding tests are needed before choosing that trade.\n\nThe low-cost digital envelope at 70 µg/√Hz and an additional common 80 µs gives **0.434807 N** in its nominal heavy endpoint. With 120 µs it reaches **0.477704 N**. The ICM's own documented decimation, selectable filters, clock and DRDY/readout timestamps still need to establish the required complete response. Its published delay combines configured filters and clocks; it cannot be replaced by an arbitrary RC pole. The native digital cases use a labeled common response/latency envelope, not an implementation of the ICM's undocumented complete transfer. Calling its output rate its sensing bandwidth would be incorrect.\n\nThe stock ADXL354 evaluation board also includes 0.1 µF output capacitance. With the documented 32 kΩ output impedance, that adds a **3.2 ms RC**, about 49.7 Hz. Such a configuration is far slower than the studied envelope. A fast prototype needs intentionally selected output capacitance and buffering. [ADI evaluation guide](https://www.analog.com/media/en/technical-documentation/user-guides/eval-adxl354-355-ug-1030.pdf).\n\nThe decisive followup preserves **four 30 s calibration-error recordings and three four-second known-k/c mixed-mechanics recordings** for each of seven sensing/drive combinations. The controller uses the same mechanics and causal measurements. Actual and identified sensor/mass/robot residuals stay separate."}, {"kind": "table", "id": "report:nested:results:acceleration-measurement:results:executed-lower-cost-response-and-calibration-experiments:table-1", "title": "Executed lower-cost response and calibration experiments · Acceleration measurement", "queryIds": ["budget_accelerometer_screen", "budget_accelerometer_parts", "budget_accelerometer_stress", "budget_dynamic_matching", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "headers": ["Required acceleration-response envelope and drive", "Passed / executed", "Worst error", "Reserve to 0.5 N"], "rows": [{"column0": "Reference density, matched 8 kHz, 100 µs current, scientific 24 V coil", "column1": "7 / 7", "column2": "0.438821 N", "column3": "0.061179 N"}, {"column0": "ADXL354-like 1.9 kHz, no extra delay, 100 µs current, scientific 24 V coil", "column1": "5 / 7", "column2": "0.516806 N", "column3": "−0.016806 N"}, {"column0": "ADXL354-like 1.9 kHz, no extra delay, 50 µs current, ideal 36 V coil", "column1": "7 / 7", "column2": "0.482489 N", "column3": "0.017511 N"}, {"column0": "ADXL354-like 1.9 kHz, extra 50 µs, 50 µs current, ideal 36 V coil", "column1": "4 / 7", "column2": "0.530965 N", "column3": "−0.030965 N"}, {"column0": "Digital 70 µg/√Hz, matched 5.1 kHz + 80 µs, 100 µs current", "column1": "3 / 7", "column2": "0.581260 N", "column3": "−0.081260 N"}, {"column0": "Digital 70 µg/√Hz, matched 5.1 kHz + 80 µs, 50 µs current", "column1": "3 / 7", "column2": "0.559963 N", "column3": "−0.059963 N"}, {"column0": "ADXL354-like 1.9 kHz, no extra delay, 50 µs current, hot real-coil 32 V output", "column1": "7 / 7", "column2": "0.482489 N", "column3": "0.017511 N"}], "rightAligned": [false, true, true, true]}, {"kind": "figure", "id": "inertial:budget_sensor_calibration_stress", "title": "Cheaper sensing under calibration and drive stress", "caption": "49 executed native recordings; failures are retained. Each row is a declared sensor response envelope, not a supplier-certified accelerometer transfer. The 0.45 N design threshold retains 0.05 N reserve.", "queryId": "budget_accelerometer_stress", "asset": "figure14"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:executed-lower-cost-response-and-calibration-experiments:part-3", "value": "The faster ADXL354-like case passes these seven inputs, but its remaining reserve is less than one third of the reference envelope's. Its hot-coil variant uses Kf=24.4 N/A, fixed R=8.896 Ω, L=4 mH and 32 V usable terminal output; brief voltage clipping occurs, and the recorded worst error stays essentially the same. This is a real-winding native simulation with a **deliberately faster 50 µs current target**, not a claim that voltage alone fixes sensing delay. Adding 50 µs common sensing latency still produces failures. The digital response envelopes fail four of seven cases even with the faster current loop.\n\nA final **seven-case tighter dynamic-matching experiment** reduces analog-response and EMA residuals from ±10% to ±1% and relative channel offsets from ±10 µs to ±2 µs, while preserving static calibration, common pipeline uncertainty, robot timing, mechanics, noise and drive. Common and per-channel response factors both remain, so their combined maximum is approximately 2.01%. The no-extra-delay ADXL354-like envelope passes at **0.489946 N worst**, only **0.010054 N reserve**. Tighter matching did not recover the desired margin; the peak need not improve monotonically because it combines deterministic error and seeded noise. Seven extra-delay matching inputs were prepared but **not executed**, and are excluded from the experiment count.\n\nThese earlier cost-study results show that a cheap accelerometer does **not preserve the faster reference sensor's margin**. The digital response envelopes also fail several cases. The new €100 PCB constraint motivates the conditional ADXL354C prototype choice below, with measured timing and independent force acceptance required. Two ADXL1002-class axes remain the faster planar comparison; three axes and sufficient simultaneous channels would be needed for spatial reconstruction."}]}, {"id": "report:nested:results:acceleration-measurement:results:first-pcb-within-the-100-chip-budget", "title": "First PCB within the €100 chip budget", "depth": 5, "path": ["Results", "Acceleration measurement", "Results", "First PCB within the €100 chip budget"], "children": [], "queryIds": ["acceleration_and_drive_parts", "budget_accelerometer_screen", "budget_accelerometer_parts", "budget_accelerometer_stress", "budget_dynamic_matching", "joint_budget_plan", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:first-pcb-within-the-100-chip-budget:part-0", "value": "##### First PCB within the €100 chip budget"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:first-pcb-within-the-100-chip-budget:part-1", "value": "Choose **one ADXL354CEZ (ADXL354C) and one ADS131M08IPBSR** for the planar prototype. Checked single-unit Netherlands distributor prices on 5 October 2026 are €61.71 and €9.45 excluding VAT: **€71.16 excluding VAT, or €86.10 with 21% VAT**. The accelerometer is one three-axis analog chip; the planar model uses two of its outputs. This is the chip subtotal only. [ADXL354CEZ price](https://www.digikey.nl/en/products/detail/analog-devices-inc/ADXL354CEZ/6557313), [ADS131M08 price](https://www.digikey.nl/en/products/detail/texas-instruments/ADS131M08IPBSR/11502308).\n\nSix amplified load-cell bridge channels plus two acceleration axes fill the M08's eight simultaneous channels. The position sensor uses a separately timestamped digital counter. For all three acceleration axes plus six bridges, two M08s give 16 channels; the accelerometer plus two ADC chips totals **€97.54 including VAT** at the same checked prices. Share clock and synchronization and measure inter-device timing. This channel-count option is not a qualification of three-dimensional sanding."}, {"kind": "figure", "id": "inertial:rl_budget_chip_cost", "title": "Accelerometer and ADC chip budget including VAT", "caption": "", "queryId": "rl_budget_parts", "asset": "figure15"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:first-pcb-within-the-100-chip-budget:part-2", "value": "At ±8 g, the reviewed acceleration noise density is **33.75 µg/√Hz** and sensitivity **100 mV/g**. The model converts that density into **0.0186557 m/s² RMS at the fixed reference noise normalization**, then lets the actual filters determine the output noise. The M08 contributes a separate **0.0020898 m/s² RMS** converter-noise injection and an ideal **0.00001403 m/s² code step**. The small code step is not the sensor's usable resolution or bias accuracy. Preserve the post-calibration **±0.005 m/s² bias and ±0.25% scale** targets; gravity tare does not cancel changing thermal bias or dynamic inertia errors. [ADXL354/355 datasheet](https://www.analog.com/media/en/technical-documentation/data-sheets/adxl354_adxl355.pdf), [M08 datasheet](https://www.ti.com/lit/ds/symlink/ads131m08.pdf).\n\nThe acquisition uses a **7.68 MHz clock and OSR 128 for 30 ksample/s per channel**. Its sinc3 group delay is approximately **49.61 µs**, before the analog chain, transfer, controller latch and computation. The model includes the converter/filter timing; it does not assume zero delay. An instrumentation amplifier with freely chosen cutoff can match channels, but cannot remove the accelerometer's internal dynamics. The ADXL354's nominal 1.9 kHz overall bandwidth is insufficient to establish the complete phase: its internal filter and mechanical response must be measured in the assembled chain.\n\nThe budget-chain experiments use a declared **1.9 kHz matched response**, retain the calibrated static/response/timing residuals, and retune the inner current response to **50 µs**. PI + feedforward passes 700 nominal cases, 32 fresh varied cases and four fresh 30 s cases, with respective worst errors **0.428526, 0.483324 and 0.492243 N**. The last reserve is only **0.007757 N**. Adding a known common 50 µs sensing delay makes two of 28 development baseline cases exceed the force limit. These experiments support an affordable bench prototype, but **do not establish the requested good margin with the cheap accelerometer**. The detailed paired neural-controller results below include all failures.\n\nThe older ADXL1002 studies explain the benefit of faster sensing; they remain useful reference evidence. The budget decision is an explicit performance tradeoff, not a claim that the ADXL354 preserves their reserve."}]}], "queryIds": ["acceleration_and_drive_parts", "budget_accelerometer_screen", "budget_accelerometer_parts", "budget_accelerometer_stress", "budget_dynamic_matching", "joint_budget_plan", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:results:part-0", "value": "#### Results"}]}, {"id": "report:nested:results:acceleration-measurement:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Acceleration measurement", "Recommendation"], "children": [], "queryIds": ["acceleration_and_drive_parts", "budget_accelerometer_screen", "budget_accelerometer_parts", "budget_accelerometer_stress", "budget_dynamic_matching", "joint_budget_plan", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:acceleration-measurement:recommendation:part-1", "value": "Use **one ADXL354C at ±8 g plus one ADS131M08** for the first planar custom PCB, approximately **€86.10 including VAT for these chips**. Mount the accelerometer rigidly on S, acquire two axes simultaneously with the force bridges and synchronize the S–A encoder. Design accessible filter and clock settings so the installed phase can be measured and the matched response adjusted. Keep the stated bias/scale calibration targets and verify noise with the sander powered. The simulated budget baseline has very little worst-case reserve; accept the hardware only after independent force measurements demonstrate the required margin."}]}], "queryIds": ["acceleration_and_drive_parts", "budget_accelerometer_screen", "budget_accelerometer_parts", "budget_accelerometer_stress", "budget_dynamic_matching", "joint_budget_plan", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acceleration-measurement:part-0", "value": "### Acceleration measurement"}]}, {"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing", "title": "Acquisition electronics: amplifier, ADC and timing", "depth": 3, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing"], "children": [{"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:intro", "title": "Intro", "depth": 4, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Intro"], "children": [], "queryIds": ["budget_adc_parts", "budget_adc_electrical", "budget_adc_screen", "budget_adc_long", "budget_adc_range", "budget_sensing_robustness", "budget_adc_hot_coil", "budget_accelerometer_screen", "budget_accelerometer_stress", "budget_sensing_execution", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:intro:part-1", "value": "The instrumentation amplifier sets the useful range before conversion. ADC noise, filter phase, clocking, readout and controller latching determine how accurately and promptly force and acceleration can be combined."}]}, {"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:question", "title": "Question", "depth": 4, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Question"], "children": [], "queryIds": ["budget_adc_parts", "budget_adc_electrical", "budget_adc_screen", "budget_adc_long", "budget_adc_range", "budget_sensing_robustness", "budget_adc_hot_coil", "budget_accelerometer_screen", "budget_accelerometer_stress", "budget_sensing_execution", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:question:part-1", "value": "What is the lowest-cost acquisition chain supported by native experiments, and why are its bandwidth and sample rate necessary rather than simply choosing a large bit count?"}]}, {"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results", "title": "Results", "depth": 4, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Results"], "children": [{"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:converters-input-scaling-and-signal-path", "title": "Converters, input scaling and signal path", "depth": 5, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Results", "Converters, input scaling and signal path"], "children": [], "queryIds": ["budget_adc_parts", "budget_adc_electrical", "report_model_schematics", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:converters-input-scaling-and-signal-path:part-0", "value": "##### Converters, input scaling and signal path"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:converters-input-scaling-and-signal-path:part-1", "value": "The ADC's bit count does not determine its useful force resolution by itself. An instrumentation amplifier maps the load cell's useful range into the converter's voltage range. The important quantities are input-referred noise, quantization after that gain, matched channel response, and the age of the sample when the controller uses it.\n\nIndicative single-IC prices retrieved on 2 October 2026 are **€63.86 for AD7606C-18**, **€19.13 for ADS8588S**, and **€9.25 for ADS131M08**, excluding VAT and shipping. These are documented regional price observations; they are not checked shopping carts. The ADC-only savings are approximately 70% and 86%. Instrumentation amplifiers, references, filtering and calibration remain part of the electronics. [Price/specification review](/home/tommie/Projects/actuator-model/acf_simulink/validation/adc_cost_component_review_20261002.md)."}, {"kind": "table", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:converters-input-scaling-and-signal-path:table-1", "title": "Converters, input scaling and signal path · Acquisition electronics: amplifier, ADC and timing", "queryIds": ["budget_adc_parts", "budget_adc_electrical", "report_model_schematics", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "headers": ["Converter", "Tested practical setting", "Force quantum at effective ±160 N", "ADC acceleration quantum with reference analog conditioning", "Intrinsic ADC response"], "rows": [{"column0": "ADS8588S, 16-bit simultaneous SAR", "column1": "50 ksample/s per channel, ±5 V", "column2": "0.004883 N", "column3": "0.018705 m/s², ADXL1002 centered gain 2", "column4": "Third-order 16 kHz analog filter, about 19.9 µs DC delay"}, {"column0": "ADS131M08, 24-bit simultaneous delta-sigma", "column1": "30 ksample/s per channel, PGA1", "column2": "0.0000191 N", "column3": "0.0000701 m/s², ADXL1002 gain 0.5", "column4": "Sinc³, OSR128 at 3.84 MHz modulator, 49.6 µs group delay"}], "rightAligned": [false, false, true, true, false]}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:converters-input-scaling-and-signal-path:part-2", "value": "Acceleration resolution is the step between adjacent codes; it is not the RMS noise or calibration accuracy. The SNR-equivalent ADC acceleration noise in these two configurations is approximately **0.01236 m/s²** for the SAR's datasheet-minimum-SNR-derived model noise and **0.01045 m/s²** for the delta-sigma typical OSR128 noise. The SAR minimum is specified at 200 ksample/s; it is a modeling provision rather than a verified noise bound at the tested 50 ksample/s. The M08 figure is typical, rather than a guaranteed maximum at the selected clock. The experiment injects ADC noise separately from physical sensor noise and avoids counting ideal quantization variance twice. Separate M08 probes double its typical noise and add 200 µs output-noise correlation. Measure both converters' assembled noise at the chosen rate. [TI SAR datasheet](https://www.ti.com/lit/ds/symlink/ads8588s.pdf), [TI delta-sigma datasheet](https://www.ti.com/lit/ds/symlink/ads131m08.pdf).\n\nThe M08 uses a **7.68 MHz master clock**, a 3.84 MHz modulator and OSR128 to produce 30 ksample/s. Reading status, eight channels and CRC requires 240 SPI bits: **15.625 µs at 15.36 MHz SPI**. The modeled **20 µs total post-conversion pipeline includes that readout**, leaving about 4.375 µs for the MCU path; it is not another 20 µs added to readout. The SAR's worst conversion plus a 128-bit read at 16 MHz is about 11.9 µs within the same total allowance. Verify those budgets on the chosen MCU.\n\nWith an analog accelerometer, **yes, the external ADC measures acceleration as well as force**. Two acceleration axes plus six raw bridge channels fit an eight-channel ADC in the current planar arrangement. A digital accelerometer uses its own internal ADC and a timestamped SPI interface; it does not consume an external ADC channel. A spatial arrangement with six bridges and three analog acceleration axes needs nine channels. Position has its own encoder interface. The bridge calibration matrix must establish the effective force-axis noise and range; raw channel specifications alone do not establish them."}, {"kind": "figure", "id": "inertial:acf_acquisition_timing", "title": "Lower-cost acquisition signal path and timing budget", "caption": "Selected M08 signal path and nominal low-frequency component delays. The full response includes frequency-dependent phase, sample age and controller latching; the 20 µs pipeline already includes SPI readout.", "queryId": "report_model_schematics", "asset": "figure16"}]}, {"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:bandwidth-rate-timing-noise-and-hot-coil-experiments", "title": "Bandwidth, rate, timing, noise and hot-coil experiments", "depth": 5, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Results", "Bandwidth, rate, timing, noise and hot-coil experiments"], "children": [], "queryIds": ["budget_adc_screen", "budget_adc_long", "budget_adc_range", "budget_sensing_robustness", "budget_adc_hot_coil", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:bandwidth-rate-timing-noise-and-hot-coil-experiments:part-0", "value": "##### Bandwidth, rate, timing, noise and hot-coil experiments"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:bandwidth-rate-timing-noise-and-hot-coil-experiments:part-1", "value": "The new private native Simulink model includes a continuous instrumentation response **before sampling**, the SAR's analog response or a genuine Sinc³ decimator, converter noise, range/quantization, an EMA with a 50 µs time-constant setting at the converter-output clock, the readout pipeline and fresh 10 kHz controller latching. Physical sensor noise density stays fixed when sample rate changes. Qualification uses every physical normal-force sample, including startup; plots are reduced only afterward. The force and acceleration response envelopes are matched, and position has a separate encoder with an aligned measurement frame.\n\nThe screen executes **168 recordings**, with two heavy/light physical endpoints and clean/seed-7 noise variants at each setting. The instrumented physical plant, estimator and controller are frozen. A separate nine-recording audit checks warm/cold compilation parity across seed, mass/force/orientation and response changes; all physical and ADC samples in the tested pairs match exactly."}, {"kind": "figure", "id": "inertial:budget_adc_bandwidth_rate", "title": "Native ADC bandwidth and rate sweep", "caption": "The numbers are worst complete-recording errors, in N, across four recordings per cell. Values above 0.500 N fail. The 0.450 N design threshold reserves 0.050 N for the physical requirement. This is a finite endpoint screen, not a continuous bandwidth proof.", "queryId": "budget_adc_screen", "asset": "figure17"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:bandwidth-rate-timing-noise-and-hot-coil-experiments:part-2", "value": "The low-bandwidth failures are substantial. With a 500 Hz matched response, the best rate still gives roughly 0.608 N error for the SAR and 0.672 N for the delta-sigma chain. A 1 kHz response is only a nominal pass at some settings. The familiar 10 Hz bump transit does not capture the controller's need to recover downstream inertia and react at bump entry/exit; the executed waveform resolves the faster dynamics.\n\nRate matters even with the same analog cutoff. At 8 kHz response, the delta-sigma group delay increases from about **49.6 µs at 30 ksample/s**, to **99.6 µs at 15 ksample/s**, to **199.6 µs at 7.5 ksample/s**. Lower rates also age the samples more before each controller latch. The controller rate remains 10 kHz in all these comparisons.\n\nThe four retained **30 s repeated-bump calibration cases** preserve the selected tighter static residuals, channel-response mismatches and robot timing errors. They expose the trade more sharply:"}, {"kind": "table", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:bandwidth-rate-timing-noise-and-hot-coil-experiments:table-1", "title": "Bandwidth, rate, timing, noise and hot-coil experiments · Acquisition electronics: amplifier, ADC and timing", "queryIds": ["budget_adc_screen", "budget_adc_long", "budget_adc_range", "budget_sensing_robustness", "budget_adc_hot_coil", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "headers": ["Converter and setting", "Completed / passed", "Worst normal-force error", "Remaining reserve to 0.5 N"], "rows": [{"column0": "ADS131M08, 15 ksample/s, 8 kHz matched response", "column1": "4 / 4", "column2": "0.494316 N", "column3": "0.005684 N"}, {"column0": "ADS131M08, 30 ksample/s, 5.1 kHz matched response", "column1": "4 / 4", "column2": "0.451330 N", "column3": "0.048670 N"}, {"column0": "ADS131M08, 30 ksample/s, 8 kHz matched response", "column1": "4 / 4", "column2": "0.438821 N", "column3": "0.061179 N"}, {"column0": "ADS8588S, 50 ksample/s, 5.1 kHz matched response", "column1": "4 / 4", "column2": "0.404214 N", "column3": "0.095786 N"}], "rightAligned": [false, true, true, true]}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:bandwidth-rate-timing-noise-and-hot-coil-experiments:part-3", "value": "Thus 15 ksample/s is a numerical pass in these four cases, but does not retain a useful design margin. Keeping **30 ksample/s** has an experimental justification. The selected **8 kHz** response retains over 0.05 N reserve in these cases; 5.1 kHz narrowly misses that preferred reserve. This establishes a tested choice, rather than proving that 8 kHz is the minimum possible cutoff. The value describes a complete engineered response target: include the accelerometer's own amplitude/phase rather than assigning it an arbitrary filter corner.\n\nFor orientation, a nominal two-pole 8 kHz response contributes **28.1 µs low-frequency delay**, Sinc³ adds **49.6 µs**, and the sampled EMA contributes **35.2 µs** at 30 ksample/s. Including the nominal pipeline gives about **132.9 µs before sample-age and controller-latch effects**. These are component delay calculations, not a single frequency-independent phase model. Native execution retains the full filters and clocked behavior. At 15 ksample/s, the decimator alone doubles its delay despite the unchanged 8 kHz analog response; the measured force-error increase above verifies that timing matters."}, {"kind": "figure", "id": "inertial:budget_adc_long_waveforms", "title": "Native long-test force waveforms", "caption": "Each curve shows the bump containing the full-recording worst sample in that setting's worst 30 s recording. The cases retain calibration error and seeded noise. Dashed lines are the force requirement; dotted lines reserve 0.05 N.", "queryId": "budget_adc_long", "asset": "figure18"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:bandwidth-rate-timing-noise-and-hot-coil-experiments:part-4", "value": "The selected M08 chain also completes a **700-case nominal grid**: five S masses, ten force targets, seven orientations, two physical drag ratios and **one noise seed, 29, per condition**. All 700 unique cases pass; worst complete-history error is **0.292803986 N**, leaving **0.207196014 N** reserve. Every one of the 1,200,001 native force samples in each four-second recording is scored. This is 700 new noise realizations, not the historical five-seed 3,500-case qualification. Preparation hashes, condition identities and disjoint partition coverage are recorded in [the grid audit](/home/tommie/Projects/actuator-model/acf_simulink/validation/budget_adc_range_grid_20261002.json)."}, {"kind": "figure", "id": "inertial:budget_sensing_response_noise", "title": "ADC noise and timing robustness probes", "caption": "Two heavy-tool recordings per probe, seeds 7/29. Each changes one acquisition property. These nominal probes are separate from the simultaneous calibration-error cases.", "queryId": "budget_sensing_robustness", "asset": "figure19"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:bandwidth-rate-timing-noise-and-hot-coil-experiments:part-5", "value": "Doubling the ADC's typical noise gives **0.339688 N** worst error; introducing a 200 µs correlation time gives **0.332057 N**. An extra acceleration-only skew of 20 µs gives **0.358505 N**, and 50 µs gives **0.381665 N**. The tested nominal cases pass, but timing consumes appreciably more margin than doubling converter noise. Keep the specified common clock and tested relative timestamp residuals rather than treating those probes as permission for arbitrary skew. Halving the physical solver step with unchanged acquisition clocks changes the paired peak by only **0.000000304 N**. Six additional quiet sensor-tone probes at 19, 49 and 99 kHz are retained separately; they do not constitute a measured sanding-vibration spectrum.\n\nThe selected **30 ksample/s / 8 kHz chain is also executed with the hot real-winding parameters**: Kf=24.4 N/A, R=8.896 Ω, L=4 mH, 32 V usable bipolar output and the unchanged **100 µs** current target. Current-domain gains are rescaled by 20/24.4 while their identified Kf residuals remain. All seven retained long/mixed cases pass, worst **0.438821 N**, with **zero voltage clipping**. Maximum requested voltage is **31.738466 V**, leaving only **0.261534 V** below the modeled output limit; peak current is **2.455697 A**. This is a new native electrical check, not reuse of the older pointwise voltage screen. At least 32 V usable output remains supported on these cases, but driver dropout and hot winding tolerances need an assembled headroom measurement. The fixed hot resistance does not simulate evolving temperature. [Selected hot-coil evidence](/home/tommie/Projects/actuator-model/acf_simulink/validation/budget_adc_hot_coil_summary_20261002.json)."}]}], "queryIds": ["budget_adc_parts", "budget_adc_electrical", "budget_adc_screen", "budget_adc_long", "budget_adc_range", "budget_sensing_robustness", "budget_adc_hot_coil", "budget_accelerometer_screen", "budget_accelerometer_stress", "budget_sensing_execution", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:results:part-0", "value": "#### Results"}]}, {"id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Acquisition electronics: amplifier, ADC and timing", "Recommendation"], "children": [], "queryIds": ["budget_adc_parts", "budget_adc_electrical", "budget_adc_screen", "budget_adc_long", "budget_adc_range", "budget_sensing_robustness", "budget_adc_hot_coil", "budget_accelerometer_screen", "budget_accelerometer_stress", "budget_sensing_execution", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:recommendation:part-1", "value": "Use **ADS131M08 at 30 ksample/s per simultaneous channel**, with **7.68 MHz clock / OSR 128**, one ADXL354C and appropriate instrumentation amplifiers on the custom PCB. Six bridge channels plus two acceleration axes fit one ADC. Keep the **50 µs EMA setting, 20 µs post-conversion pipeline and fresh 10 kHz control** in the tested acquisition contract. The final budget experiments use a **1.9 kHz matched response envelope** and **50 µs current response**; the earlier 8 kHz studies above belong to the faster reference sensors.\n\nMeasure the complete force and acceleration responses, including the accelerometer's internal dynamics, sinc3 delay, SPI and controller latching. Match their effective timestamps and the estimated surface normal before inertia reconstruction. The instrumentation amplifier cutoff can be selected to achieve this matching; it cannot cancel a sensor's delay. The additional-50-µs experiment below fails two of 28 deterministic development conditions, making timing a demonstrated limitation, not merely a sampling-theory concern.\n\nRetain **±0.01 N force zero, ±0.005 m/s² acceleration bias** and the other tighter calibration targets. At S=2 kg, that acceleration bias already produces 0.01 N inertia error. The cheaper chain passes the new baseline force tests but leaves only 0.007757 N in the worst long recording. Require **independent reference-force error plus uncertainty ≤0.45 N** during complete powered-sanding tests before accepting it.\n\nThe public desktop model retains the scientific-reference chain. The new budget model, compiled native banks and hash-checking replay launcher are retained under `acf_simulink/validation/rl_budget3h_20261005/` and described in [the unified-study run guide](/home/tommie/Projects/actuator-model/acf_simulink/experiments/rl_budget3h_20261005/README.md). The ADXL354C/M08 chips cost about €86.10 including VAT; amplification, clock, power and PCB costs are additional."}]}], "queryIds": ["budget_adc_parts", "budget_adc_electrical", "budget_adc_screen", "budget_adc_long", "budget_adc_range", "budget_sensing_robustness", "budget_adc_hot_coil", "budget_accelerometer_screen", "budget_accelerometer_stress", "budget_sensing_execution", "rl_budget_parts", "rl_budget_sensing_contract", "rl_fresh_tests", "rl_long_tests", "rl_nominal_grid", "rl_budget_response_limits"], "fragments": [{"kind": "prose", "id": "report:nested:results:acquisition-electronics-amplifier-adc-and-timing:part-0", "value": "### Acquisition electronics: amplifier, ADC and timing"}]}, {"id": "report:nested:results:fast-force-controller", "title": "Fast force controller", "depth": 3, "path": ["Results", "Fast force controller"], "children": [{"id": "report:nested:results:fast-force-controller:intro", "title": "Intro", "depth": 4, "path": ["Results", "Fast force controller", "Intro"], "children": [], "queryIds": ["reference_PI_gains", "reference_strategies", "cell_stiffness", "lower_spring_search", "lower_series_repeated_reference", "lower_series_force_balance", "force_error_balance", "final_current_response", "final_long_joint_budget", "final_static_calibration_long", "paired_static_peak_diagnostic", "selected_settings"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:intro:part-1", "value": "The fast controller combines moderate force-error feedback with compensation for gravity, observed tool inertia, drag and the compliant lower mechanism. Its inputs remain causal; surface truth belongs to the physical plant and scoring."}]}, {"id": "report:nested:results:fast-force-controller:question", "title": "Question", "depth": 4, "path": ["Results", "Fast force controller", "Question"], "children": [], "queryIds": ["reference_PI_gains", "reference_strategies", "cell_stiffness", "lower_spring_search", "lower_series_repeated_reference", "lower_series_force_balance", "force_error_balance", "final_current_response", "final_long_joint_budget", "final_static_calibration_long", "paired_static_peak_diagnostic", "selected_settings"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:question:part-1", "value": "Does PI, PID or a more advanced causal strategy solve the sharp bump with useful margin, and which dynamics actually limit further improvement?"}]}, {"id": "report:nested:results:fast-force-controller:results", "title": "Results", "depth": 4, "path": ["Results", "Fast force controller", "Results"], "children": [{"id": "report:nested:results:fast-force-controller:results:controller-architecture-and-causal-inputs", "title": "Controller architecture and causal inputs", "depth": 5, "path": ["Results", "Fast force controller", "Results", "Controller architecture and causal inputs"], "children": [], "queryIds": ["reference_PI_gains", "reference_strategies", "cell_stiffness", "lower_spring_search", "lower_series_repeated_reference", "lower_series_force_balance", "force_error_balance", "final_current_response", "final_long_joint_budget", "final_static_calibration_long", "paired_static_peak_diagnostic", "selected_settings"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:results:controller-architecture-and-causal-inputs:part-0", "value": "##### Controller architecture and causal inputs"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:controller-architecture-and-causal-inputs:part-1", "value": "The fast loop regulates reconstructed normal force. A PI/PID correction combines with gravity compensation, measured-acceleration feedforward and a measured correction for surface slope and sanding drag. The two-state motion observer estimates S–A separation and velocity from relative position, measured S acceleration and the causal robot-motion predictor. With upper A rigidly attached to the prescribed robot boundary, these give an estimate of the tool's axial velocity and therefore local surface slope. An upper compliant attachment needs an additional estimate of A's motion before this reconstruction can be qualified."}, {"kind": "figure", "id": "inertial:acf_causal_control_loops", "title": "Fast force control and gated delayed robot recentering", "caption": "The force loop corrects fast disturbances. The robot loop manages travel slowly; closing its force-stability gate leaves already-issued commands in the queue and predictor.", "queryId": "report_model_schematics", "asset": "figure20"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:controller-architecture-and-causal-inputs:part-2", "value": "The geometry feedforward uses an estimated ratio of tangential drag to pressing force. From the reconstructed reaction vector and estimated slope:\n\n```text\nmu_hat_raw = −(Rx_hat + s_hat Rz_hat) / (Rz_hat − s_hat Rx_hat)\nRz_request = Nref (1 − mu_hat s_hat) / sqrt(1+s_hat²)\n```\n\nThe ratio is accepted only while estimated pressing force and the denominator exceed 1 N, is bounded to [−1,1], and is smoothed with a 5 ms EMA. It starts at zero and holds its previous value when invalid. This supplies measured drag compensation without assuming that the controller knows the plant's friction coefficient. A radial fluctuation of reaction force cancels in the ratio, which helps avoid turning geometry feedforward into an additional high-frequency force-feedback path. Force reconstruction itself still uses the measured vector projected onto the estimated normal.\n\nFor an identified coil force constant Kf and positive error `e = Nhat − Nref`, the main current request is:\n\n```text\nIrequest = Ih_hold + (Rz_request − Nref)/Kf\n           − (mB_identified + mS_identified) aS_FF/Kf\n           + friction_estimate(vgap_hat)/Kf\n           + lower_inverse_current\n           + feedback_filter(−Kp e − Ki integral(e) − Kd derivative_filtered(e))\n```\n\nThe measured-acceleration term corrects the disturbance after it is observed. It supplies no future surface information. A separate optional causal derivative lead and feedforward filter trade transient delay against amplification of accelerometer noise. The identified masses and force constant determine these commands; the physical plant retains its actual masses, winding and force constant. Saturation and antiwindup keep the integrator consistent with available current. PI gains are expressed explicitly in A/N and A/(N·s); changing Kf does not silently change user gains.\n\nThe coil's own current regulator retains winding resistance, inductance, back EMF and supply clipping. Actual current follows its physical winding state, rather than jumping instantly to the request. The force loop and current loop are separate: a fast software update does not establish either loop's physical bandwidth.\n\nFast feedback and feedforward have different filtering needs. Feedback must avoid exciting delayed structural modes; feedforward needs to follow the tool's measured acceleration promptly. Filtering the entire current request can stabilize a mode while also delaying the useful acceleration correction. The structural controller search therefore examines both total-current mode suppression and filtering of the feedback correction alone, with the same physical sensor inputs. Every selected filter must be tested with repeated bumps and changed structural frequency, rather than accepted from one quiet trace."}]}, {"id": "report:nested:results:fast-force-controller:results:the-lower-link-inverse", "title": "The lower-link inverse", "depth": 5, "path": ["Results", "Fast force controller", "Results", "The lower-link inverse"], "children": [], "queryIds": ["reference_PI_gains", "reference_strategies", "cell_stiffness", "lower_spring_search", "lower_series_repeated_reference", "lower_series_force_balance", "force_error_balance", "final_current_response", "final_long_joint_budget", "final_static_calibration_long", "paired_static_peak_diagnostic", "selected_settings"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:results:the-lower-link-inverse:part-0", "value": "##### The lower-link inverse"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:the-lower-link-inverse:part-1", "value": "A lower spring/damper gives B and S different accelerations. Compensating only the measured S acceleration as though B always moved with S leaves a substantial error. Increasing PI gain or adding derivative action did not recover the required margin in the tested compliant designs.\n\nLet `q` be the change in S–B separation from its loaded equilibrium, and let `deltaL` be the **actual** lower-link load change. The physical constitutive law and force balance use that actual motion. Separately, the controller forms `deltaL_desired` from measured S acceleration and the requested axial contact reaction:\n\n```text\ndeltaL_desired = (Rz_request − Nref) − mS_identified aS_measured\ndeltaL = k1 q + c1 dq/dt\naB = aS − d²q/dt²\nFa_net = Rz − (mB+mS)(g_axis+aS) + mB d²q/dt²\nFcoil = Fa_net + guide_friction\n```\n\nThe last acceleration term is the missing B–S relative-motion correction. The selected native branch converts measured desired load into an extra current:\n\n```text\nI_lower_inverse(s) = (mB_identified / Kf_identified)\n                     × s² / (k1_identified + c1_identified s)\n                     × LP2(s, 1500 Hz, damping 0.707)\n                     × deltaL_desired(s)\n```\n\nThe two-pole low-pass makes this a proper, causal transfer rather than an unbounded ideal differentiation. It is implemented with ordinary Sum, Gain and Discrete Transfer Fcn blocks. The controller uses recorded sensor inputs and known mechanism parameters; it receives neither the true tool acceleration nor the bump trajectory. The filter and identified coefficients are prepared before simulation, while the physical force and motion still run in native blocks.\n\nThis correction helps the actuator accelerate B differently from S while the lower compliance carries the requested load. In the retained worst repeated-bump trace it reaches about **0.50 A**, equivalent to **9.94 N** for the generic 20 N/A coil. It changes the required current waveform appreciably even though the short bump itself is only 1 mm high."}, {"kind": "table", "id": "report:nested:results:fast-force-controller:results:the-lower-link-inverse:table-1", "title": "The lower-link inverse · Fast force controller", "queryIds": ["reference_PI_gains", "reference_strategies", "cell_stiffness", "lower_spring_search", "lower_series_repeated_reference", "lower_series_force_balance", "force_error_balance", "final_current_response", "final_long_joint_budget", "final_static_calibration_long", "paired_static_peak_diagnostic", "selected_settings"], "headers": ["Selected core setting", "Value", "Meaning"], "rows": [{"column0": "Upper connection", "column1": "Rigid", "column2": "A follows the modeled robot boundary"}, {"column0": "Lower opposed-pair net stiffness", "column1": "19,746 N/m", "column2": "Two approximately 9.873 N/mm springs"}, {"column0": "Lower parallel damping", "column1": "60 N·s/m", "column2": "About 2 N peak damping force in the retained repeated test"}, {"column0": "Common preload", "column1": "33.6 N per spring", "column2": "Both springs remain seated throughout the tested motion"}, {"column0": "Proportional / integral gain", "column1": "0.30 A/N / 20 A/(N·s)", "column2": "Moderate force correction around the feedforward command"}, {"column0": "Derivative gain", "column1": "0", "column2": "No derivative term in the selected PI preset"}, {"column0": "Feedback-only filter", "column1": "1 kHz, two poles, damping 0.707", "column2": "Limits force-feedback noise without filtering every feedforward term"}, {"column0": "Lower-link inverse filter", "column1": "1.5 kHz, two poles, damping 0.707", "column2": "Limits derivative effort in the causal mechanism inverse"}, {"column0": "Guide-velocity prediction", "column1": "400 µs", "column2": "A measured-motion timing correction, not surface preview"}, {"column0": "Measured drag-ratio filter", "column1": "5 ms", "column2": "Smooths the inferred tangential/normal force ratio"}, {"column0": "Force/current control update", "column1": "10 kHz", "column2": "Distinct from the actuator's actual current bandwidth"}, {"column0": "Physical integration step", "column1": "10 µs", "column2": "Reference mechanics checked against 5 and 2.5 µs; final acquisition refinement reported with its own source"}], "rightAligned": [false, true, false]}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:the-lower-link-inverse:part-2", "value": "These are coefficients for the stated masses, generic coil and selected sensing model. The known tool mass, holder mass, force constant and lower-link coefficients must be updated together. Deliberate calibration-error tests retain a distinction between actual plant parameters and the controller's identified values."}]}, {"id": "report:nested:results:fast-force-controller:results:equal-cohort-pi-pid-feedforward-comparison", "title": "Equal-cohort PI/PID/feedforward comparison", "depth": 5, "path": ["Results", "Fast force controller", "Results", "Equal-cohort PI/PID/feedforward comparison"], "children": [], "queryIds": ["reference_PI_gains", "reference_strategies"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:results:equal-cohort-pi-pid-feedforward-comparison:part-0", "value": "##### Equal-cohort PI/PID/feedforward comparison"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:equal-cohort-pi-pid-feedforward-comparison:part-1", "value": "The first controller screen uses the same physical measurements and force reconstruction for every strategy. It contains **72 gain-search recordings and 56 strategy recordings**, each scored from its full native history. These recordings use rigid attachments as a reference while the finite-sensor structural controller is being qualified."}, {"kind": "table", "id": "report:nested:results:fast-force-controller:results:equal-cohort-pi-pid-feedforward-comparison:table-1", "title": "Equal-cohort PI/PID/feedforward comparison · Fast force controller", "queryIds": ["reference_PI_gains", "reference_strategies"], "headers": ["Rigid-reference strategy, equal eight-case cohort", "Worst normal-force error", "Cases passing ±0.5 N"], "rows": [{"column0": "PI with measured-acceleration, geometry and guide-friction feedforward", "column1": "0.374 N", "column2": "8/8"}, {"column0": "Same, with small filtered derivative action", "column1": "0.378 N", "column2": "8/8"}, {"column0": "Same, with half guide-friction feedforward", "column1": "0.380 N", "column2": "8/8"}, {"column0": "Same, with guide-friction feedforward removed", "column1": "0.385 N", "column2": "8/8"}, {"column0": "Geometry/friction feedforward, without acceleration feedforward", "column1": "1.667 N", "column2": "0/8"}, {"column0": "PI with static holding current only", "column1": "1.840 N", "column2": "0/8"}], "rightAligned": [false, true, true]}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:equal-cohort-pi-pid-feedforward-comparison:part-2", "value": "The cohort includes the light and heavy tool endpoints, a clean run and three noise seeds at each. Increasing proportional or integral gain increased the worst seeded error. This supports a moderate PI correction with measured feedforward; derivative action is not automatically an improvement. The selected mechanism and its measured-acquisition results are evaluated separately below; the rigid-reference comparison is used to explain the control choice."}, {"kind": "figure", "id": "inertial:inertial_controller_reference_comparison", "title": "Measured acceleration improves the equal-cohort controller comparison", "caption": "56 completed native recordings, with the same reconstructed normal-force measurement for every strategy. This reference uses rigid connections; the real finite-cell design is qualified separately.", "queryId": "reference_strategies", "asset": "figure21"}, {"kind": "figure", "id": "inertial:inertial_PI_reference_gain_search", "title": "PI gain sweep for the rigid reference", "caption": "72 completed native recordings, eight common cases per gain pair. Every cell reports the worst full-history normal-force error, including startup.", "queryId": "reference_PI_gains", "asset": "figure22"}]}, {"id": "report:nested:results:fast-force-controller:results:finite-cell-structural-sensitivity", "title": "Finite-cell structural sensitivity", "depth": 5, "path": ["Results", "Fast force controller", "Results", "Finite-cell structural sensitivity"], "children": [], "queryIds": ["cell_stiffness"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:results:finite-cell-structural-sensitivity:part-0", "value": "##### Finite-cell structural sensitivity"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:finite-cell-structural-sensitivity:part-1", "value": "The finite load-cell study changes the structural problem substantially. In 72 recordings over six cell stiffnesses, the same measured-drag geometry strategy retains contact without voltage or current clipping. With Kp=0.06 A/N, Ki=20 A/(N·s) and a feedback-only two-pole 1 kHz filter with damping 1.5, **35 of 36 cases** meet the force band. The 64 MN/m cohort's worst error is **0.492 N**, leaving only 0.008 N reserve; the 110 MN/m cohort has a 0.570 N noise-sensitive failure. Thus short nominal passes alone are insufficient for a practical recommendation.\n\nA separate six-case 110 MN/m study applies a 1 ms acceleration-feedforward filter and causal derivative prediction. All six pass, with **0.471 N** worst error. The corresponding eight-case 64 MN/m cohort reaches **0.493 N**: smoothing reduces stationary structural noise but consumes transient margin. These are comparative structural results; the final full-range timing and calibration qualification is reported separately below."}, {"kind": "figure", "id": "inertial:inertial_cell_stiffness_sensitivity", "title": "Load-cell stiffness and controller sensitivity", "caption": "72 native stiffness/controller recordings plus six filtered-feedforward recordings at 110 MN/m. Every point is a common cohort's worst full-history error. The star is a separately tested controller setting, rather than an interpolated filtered-controller curve.", "queryId": "cell_stiffness", "asset": "figure23"}]}, {"id": "report:nested:results:fast-force-controller:results:selected-core-controller-and-repeated-bump-test", "title": "Selected core controller and repeated bump test", "depth": 5, "path": ["Results", "Fast force controller", "Results", "Selected core controller and repeated bump test"], "children": [], "queryIds": ["lower_series_repeated_reference"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:results:selected-core-controller-and-repeated-bump-test:part-0", "value": "##### Selected core controller and repeated bump test"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:selected-core-controller-and-repeated-bump-test:part-1", "value": "The selected core candidate then passes **32 short endpoint recordings** and **three 10 s repeated-bump recordings** with a heavy 2 kg S, 50 N, 90°, drag ratio 0.3, and noise seeds 7, 29 and 1729. The repeated recordings cross seven sharp bumps each. The worst error is **0.37263 N**, leaving **0.12737 N** of nominal force reserve; there are no current/voltage clips, contact losses or travel-stop hits. These recordings use the matched 100 µs response-envelope reference. Final acquisition, calibration and full-grid results are reported separately so they are not confused with this core controller test."}, {"kind": "figure", "id": "inertial:inertial_mechanics_selected_repeated", "title": "Native repeated sharp-bump force, current and spring motion", "caption": "Retained seed-29 heavy-tool recording, scored at every original 10 µs sample. The display uses min/max envelopes to preserve peaks. Current limits are ±3.5 A; the force band is ±0.5 N.", "queryId": "lower_series_repeated_reference", "asset": "figure24"}]}, {"id": "report:nested:results:fast-force-controller:results:observed-limits-and-faster-drive-tradeoffs", "title": "Observed limits and faster-drive tradeoffs", "depth": 5, "path": ["Results", "Fast force controller", "Results", "Observed limits and faster-drive tradeoffs"], "children": [], "queryIds": ["lower_series_force_balance", "force_error_balance", "final_current_response", "final_long_joint_budget", "final_static_calibration_long", "paired_static_peak_diagnostic"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:results:observed-limits-and-faster-drive-tradeoffs:part-0", "value": "##### Observed limits and faster-drive tradeoffs"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:observed-limits-and-faster-drive-tradeoffs:part-1", "value": "In the selected lower-series reference, the worst 80-case endpoint reaches **0.33570 N** at about **0.77 ms after bump entry**. Its exact native force balance shows +6.695 N of B-side relative inertia and −6.717 N from the causal lower-link inverse: the combined residual is only −0.022 N. Other simultaneous contributions are +0.848 N current tracking, +0.211 N acceleration timing, +0.406 N guide-friction estimation, +0.008 N geometry and −1.114 N filtered PI correction. They sum to the actual normal-force error within 3.3×10⁻¹⁴ N. The terms interact and partly cancel; their individual peaks must not be treated as independent error allowances.\n\nThe guide-friction residual has a clear mechanical cause. The position/acceleration observer supplies S–A motion, while guide friction acts on B–A motion. These velocities differ when the lower spring moves. Estimating that difference from measured link load is possible, but differentiation also amplifies load-cell noise near a Coulomb-friction reversal. The delivered qualified controller keeps the tested approximation; a new guide observer needs its own native qualification. More voltage does not correct a wrong motion estimate.\n\nFor comparison, the stiff finite-cell baseline reaches its 0.492 N peak about 0.44 ms after bump entry. An exact reconstruction from its retained native signals attributes approximately **0.095 N to current tracking, 0.184 N to acceleration timing and 0.216 N to B–S relative inertia**, with smaller geometry/friction terms and about −0.009 N PI correction. Physical acceleration is used for these diagnostic balances only; the controller receives measured acceleration.\n\nThe loaded cell mode is visible near 1.6 kHz. Halving the current-response target from 100 to 50 µs does not solve it: the three equal eight-case cohorts have worst errors of **0.526, 0.594 and 0.510 N**, depending on feedforward shaping. All retain contact, and none clip voltage or current. The faster drive more strongly excites the cell through measurement noise. A supply increase cannot cure a force error caused by unsaturated sensor delay and structural noise; voltage helps when the winding actually runs out of voltage for the required slew."}, {"kind": "figure", "id": "inertial:inertial_performance_limit_decomposition", "title": "Native force-error balance and the faster-drive tradeoff", "caption": "The upper panel uses every retained 10 µs sample around the first bump entry. The lower panel decomposes each setting's worst retained endpoint trace; its peak time and noise seed can differ. This is a balance analysis of five existing recordings, rather than an additional experiment.", "queryId": "force_error_balance", "asset": "figure25"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:observed-limits-and-faster-drive-tradeoffs:part-2", "value": "These stiff-cell results motivated synchronized low-latency analog acquisition, response matching and separate feedback/feedforward shaping. More proportional gain, more prediction or a faster current loop are not universal improvements. The current-response comparison for the selected compliant mechanism is separate from this earlier stiff-cell result.\n\nThe robot predictor is another practical limit. In the core 96-case calibration screen, **91 cases pass and five fail**, all caused by actual robot command delay differing from the assumed 80 ms. With a 120 ms actual delay, one heavy-tool trace reaches **0.777 N after the bump has ended**, without clipping, a stop or packing failure. At that instant the actual robot velocity is about +2.14 mm/s while the prediction is −2.20 mm/s; the observer infers an apparent slope on a flat surface. The force gate can see a stable reconstructed force even while the true surface force is wrong. Therefore the gate and predictor must be used together with an identified loaded robot response. The final sensor version's joint calibration tests determine the acceptable timing allowance.\n\nFor the **selected compliant mechanism and final acquisition**, twelve complete 10 s native recordings compare 50, 100 and 150 µs current-response targets at 24 and 36 V, using two repeated-heavy noise seeds. Each recording crosses seven bumps. All twelve pass. Worst force errors are **0.31271, 0.34532 and 0.37230 N**, respectively; the corresponding nominal margins are **0.18729, 0.15468 and 0.12770 N**."}, {"kind": "figure", "id": "inertial:inertial_final_current_response", "title": "Current-response speed and voltage headroom in the selected mechanism", "caption": "12 native repeated-heavy recordings. The 24/36 V comparison changes available voltage separately from current-response tuning; all original samples are scored.", "queryId": "final_current_response", "asset": "figure26"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:results:observed-limits-and-faster-drive-tradeoffs:part-3", "value": "The faster 50 µs response improves this sampled worst by only **0.03261 N** compared with 100 µs, while doubling the modeled first-order bandwidth from about 1.59 to 3.18 kHz and raising requested voltage to **28.05 V**. At 24 V it clips for 42–43 native 10 µs samples, about 0.42–0.43 ms total over 10 s. A 36 V ideal bus removes that clipping and changes the waveform, but leaves the cohort's peak force error equal to about 10⁻¹² N. At 100 and 150 µs, all 72 logged channels in each matched 24/36 V recording pair are bitwise identical because neither bus clips. Faster current response slightly increases flat/noise RMS while reducing the sharp transient peak. The selected **100 µs** target gives useful nominal margin with lower required bandwidth; 50 µs is a separately tested development option, not the full-grid or joint-calibration target. A useful local timing estimate is `S × peak jerk × time mismatch`: at S=2 kg, 384 m/s³ and 50 µs, this is about **0.0384 N** of tool-inertia mismatch. It explains why tens of microseconds matter, while remaining an engineering sensitivity estimate rather than a prediction of the complete closed-loop improvement.\n\nThe selected current-loop study has settled-flat peaks around **0.084–0.091 N**, while its global maxima occur during bump entry/recovery. The worst four-second joint-calibration trace likewise peaks at **0.58 ms after entry**: true normal force is 50.448 N while its estimate is 50.267 N, and actual versus measured S acceleration is 0.215 versus 0.126 m/s². At that instant the actual/predicted robot speed differs by only 0.081 µm/s, so this peak primarily exposes sensing/drive timing. The exact balance is +0.633 N current tracking, −7.268 N command/feedforward and +7.083 N B-relative inertia, summing within 2.1×10⁻¹⁴ N. The lower inverse deliberately cancels the large relative-inertia contribution; it is not a standalone unavoidable 7 N error.\n\nThe next useful performance work is to measure and match installed sensor/driver phase, reduce friction and calibrate the lower inverse under the real mount. Raising supply voltage beyond the verified usable headroom leaves those errors unchanged. A faster current loop can provide a modest improvement once its noise, hot-load stability and wider calibration envelope are demonstrated.\n\nThe longer repeats show why calibration deserves priority: the original static residuals consume about 0.15 N as sustained offset, and halving them recovers about 0.075 N of worst error without changing drive bandwidth or timing. This is a larger observed improvement in its paired cohort than the 0.033 N nominal benefit from doubling current bandwidth in the separate drive study. Those are different cohorts, so the benefits are not additive. Lower tool mass also reduces inertia and timing sensitivity directly; keep S light where the sanding task allows it.\n\nThe paired long-worst diagnosis makes that distinction explicit. On the same quiet flat interval, true-force offset falls from **0.148810 to 0.074255 N**, while peak error falls from 0.490396 to 0.415311 N. Subtracting that offset leaves nearly unchanged transient excess: **0.341586 versus 0.341055 N**. The robot is essentially stationary at both late peaks, and both gates are ready. Calibration removes a hidden steady pressing offset; it does not materially improve transient tracking or reduce noise in this comparison."}]}], "queryIds": ["reference_PI_gains", "reference_strategies", "cell_stiffness", "lower_spring_search", "lower_series_repeated_reference", "lower_series_force_balance", "force_error_balance", "final_current_response", "final_long_joint_budget", "final_static_calibration_long", "paired_static_peak_diagnostic", "selected_settings"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:results:part-0", "value": "#### Results"}]}, {"id": "report:nested:results:fast-force-controller:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Fast force controller", "Recommendation"], "children": [], "queryIds": ["reference_PI_gains", "reference_strategies", "cell_stiffness", "lower_spring_search", "lower_series_repeated_reference", "lower_series_force_balance", "force_error_balance", "final_current_response", "final_long_joint_budget", "final_static_calibration_long", "paired_static_peak_diagnostic", "selected_settings"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:fast-force-controller:recommendation:part-1", "value": "Use **measured-inertia Feedforward PI** with the causal lower-link inverse. The generic 20 N/A coil setting is **Kp = 0.3 A/N**, **Ki = 20 A/(N·s)** and **Kd = 0**, with a **1 kHz feedback-only filter** and **1.5 kHz inverse roll-off**. Identify assembled k/c, downstream mass and Kf; rescale current-domain gains for another force constant.\n\nRetain physical current dynamics, saturation and antiwindup. Raising voltage helps only when clipping limits slew; a deliberately faster current loop needs its own sensing/noise and thermal qualification. Assess the unified learned controller separately below before changing this prototype baseline."}]}], "queryIds": ["reference_PI_gains", "reference_strategies", "cell_stiffness", "lower_spring_search", "lower_series_repeated_reference", "lower_series_force_balance", "force_error_balance", "final_current_response", "final_long_joint_budget", "final_static_calibration_long", "paired_static_peak_diagnostic", "selected_settings"], "fragments": [{"kind": "prose", "id": "report:nested:results:fast-force-controller:part-0", "value": "### Fast force controller"}]}, {"id": "report:nested:results:robot-commands-and-recentering", "title": "Robot commands and recentering", "depth": 3, "path": ["Results", "Robot commands and recentering"], "children": [{"id": "report:nested:results:robot-commands-and-recentering:intro", "title": "Intro", "depth": 4, "path": ["Results", "Robot commands and recentering", "Intro"], "children": [], "queryIds": ["selected_settings", "final_robot_OAT", "joint_budget_plan", "rl_method_contract", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:intro:part-1", "value": "The robot provides slow gross motion and recenters the short-stroke actuator. Its delay makes unqualified force chasing risky, and commands already transmitted continue to affect motion after new commands are blocked."}]}, {"id": "report:nested:results:robot-commands-and-recentering:question", "title": "Question", "depth": 4, "path": ["Results", "Robot commands and recentering", "Question"], "children": [], "queryIds": ["selected_settings", "final_robot_OAT", "joint_budget_plan", "rl_method_contract", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:question:part-1", "value": "When is force stable enough to issue a recentering command, and how should queued motion and loaded robot delay constrain that command?"}]}, {"id": "report:nested:results:robot-commands-and-recentering:results", "title": "Results", "depth": 4, "path": ["Results", "Robot commands and recentering", "Results"], "children": [{"id": "report:nested:results:robot-commands-and-recentering:results:stability-gate-delay-aware-gain-and-command-prediction", "title": "Stability gate, delay-aware gain and command prediction", "depth": 5, "path": ["Results", "Robot commands and recentering", "Results", "Stability gate, delay-aware gain and command prediction"], "children": [], "queryIds": ["selected_settings", "final_robot_OAT", "joint_budget_plan", "rl_method_contract", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:results:stability-gate-delay-aware-gain-and-command-prediction:part-0", "value": "##### Stability gate, delay-aware gain and command prediction"}, {"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:results:stability-gate-delay-aware-gain-and-command-prediction:part-1", "value": "The robot loop recenters actuator travel slowly. Its output should not chase a 0.1 s bump through a delayed industrial robot. The existing gate checks reconstructed force error within ±0.2 N, filtered trend within 2 N/s and a 100 ms stable interval. A second detector evaluates force variation at every 10 kHz force sample: a 100 ms error mean, 20 ms fluctuation-variance filter and an 0.08 N RMS threshold. Every failing fast sample resets the stable dwell, including threshold crossings between robot ticks. Robot commands are issued at 100 Hz only after the dwell is complete. These thresholds are explicit control settings, rather than a promise that filtered force alone bounds the true workpiece force.\n\nThe requested recenter gain is bounded using expected robot delay, response time and gate timing. For the modeled 80 ms command delay, 60 ms response and two 100 ms gate intervals, an 0.8/s request is capped at approximately 0.735/s. A physical robot still needs a measured loaded response before accepting this gain.\n\nClosing the gate suppresses new correction commands. It cannot cancel commands already in a delay queue. The command predictor therefore models already-issued motion; it is not a preview of future bumps. The selected recordings test that distinction explicitly.\n\nThe prescribed-motion robot model is suitable for studying command delay and stroke management. It does not yet represent force-induced robot compliance, joint dynamics or a controller that changes its own behavior under load. Those properties require measurements of the actual robot and a low-gain prototype recenter test before increasing correction gain."}]}, {"id": "report:nested:results:robot-commands-and-recentering:results:accepted-travel-band-and-sustained-motion", "title": "Accepted travel band and sustained motion", "depth": 5, "path": ["Results", "Robot commands and recentering", "Results", "Accepted travel band and sustained motion"], "children": [], "queryIds": ["selected_settings", "final_robot_OAT", "joint_budget_plan", "rl_method_contract", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:results:accepted-travel-band-and-sustained-motion:part-0", "value": "##### Accepted travel band and sustained motion"}, {"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:results:accepted-travel-band-and-sustained-motion:part-1", "value": "The current objective accepts **±7.5 mm about the 12.5 mm stroke midpoint without a centering penalty**. The 0–25 mm physical stops remain unchanged, leaving 5 mm between either accepted-band edge and the corresponding stop. The learned controller may leave the robot stationary anywhere inside that band. Excursion outside it adds an increasing soft cost; contact loss and a physical stop still fail the run.\n\nThe raw learned correction can request up to ±10 mm/s, then the existing delay-aware sign/amplitude envelope, force gate and robot limits constrain the actual command. The native envelope permits only about 5.15 mm/s at a 7.5 mm offset. With a sustained 5 mm/s outward programmed motion, the steady balance is therefore near a 7.3 mm offset, leaving little band margin. Allowing a broad band does not justify waiting until its edge before compensating a known delayed command.\n\nDevelopment includes bounded programs that reverse, constant nominal motion from the beginning of the recording, and initial offsets outside the accepted band but inside the physical stops. Full histories report maximum and final band excess and time inside; an intentional initial excursion is not mislabeled as a failed physical stop. Queued nominal and correction commands remain active after the gate closes. Fresh long tests separately assess whether the selected policy maintains travel under continued motion."}]}], "queryIds": ["selected_settings", "final_robot_OAT", "joint_budget_plan", "rl_method_contract", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:results:part-0", "value": "#### Results"}]}, {"id": "report:nested:results:robot-commands-and-recentering:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Robot commands and recentering", "Recommendation"], "children": [], "queryIds": ["selected_settings", "final_robot_OAT", "joint_budget_plan", "rl_method_contract", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:recommendation:part-1", "value": "Keep the robot update at **100 Hz**, with the slow force-error/trend gate and the **0.08 N RMS variation detector** evaluated at fast force samples. Require the **100 ms stable dwell** before new recentering corrections. Use the loaded-delay/response gain cap, track issued commands explicitly and preserve their queued effect when the gate closes.\n\nThe evaluated reference is **80 ms delay / 60 ms response**, with **±5 ms identification residuals**. Measure the actual loaded robot and begin with a low recenter gain. Keep ±7.5 mm as an acceptable travel region, anticipate already-issued motion and retain the same hard gate and command envelope for learned control."}]}], "queryIds": ["selected_settings", "final_robot_OAT", "joint_budget_plan", "rl_method_contract", "rl_fresh_tests", "rl_long_tests"], "fragments": [{"kind": "prose", "id": "report:nested:results:robot-commands-and-recentering:part-0", "value": "### Robot commands and recentering"}]}, {"id": "report:nested:results:learned-control-policy", "title": "Learned control policy", "depth": 3, "path": ["Results", "Learned control policy"], "children": [{"id": "report:nested:results:learned-control-policy:intro", "title": "Intro", "depth": 4, "path": ["Results", "Learned control policy", "Intro"], "children": [], "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:intro:part-1", "value": "Our goal is one compact controller choosing voice-coil current and robot correction from causal measurements and known tool parameters. The workpiece's normal force must stay within ±0.5 N through the 1 mm × 10 mm bump scanned at 100 mm/s, across 5–50 N, S = 0.1–2 kg and fixed orientations of 0–90°. B is 0.6 kg. Travel within ±7.5 mm of center has zero centering cost.\n\nBoth actions use one shared history: current updates every 100 µs and new robot corrections are permitted at 100 Hz. Native Simulink mechanics, contact, sensing, current regulation, command delays and limits remain the environment.\n\nThe final locked candidate uses an **ADXL354C-like ±8 g sensing model with ADS131M08 acquisition at 30 ksample/s**, a declared matched **1.9 kHz complete-response envelope**, and **50 µs current response at 32 V usable bipolar output**. Those same inputs apply to the paired deterministic baseline. Earlier faster-sensor development, memory and voltage tests retain their own settings. The complete installed ADXL354 transfer function is not established by its bandwidth specification."}]}, {"id": "report:nested:results:learned-control-policy:question", "title": "Question", "depth": 4, "path": ["Results", "Learned control policy", "Question"], "children": [], "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:question:part-1", "value": "Can the policy learn fast force control and delayed robot correction using measurable inputs and the existing stability constraints? A good result needs complete force recordings and useful robot actions; low force error alone can hide a robot that receives no commands."}]}, {"id": "report:nested:results:learned-control-policy:results", "title": "Results", "depth": 4, "path": ["Results", "Learned control policy", "Results"], "children": [{"id": "report:nested:results:learned-control-policy:results:design-and-causal-inputs", "title": "Design and causal inputs", "depth": 5, "path": ["Results", "Learned control policy", "Results", "Design and causal inputs"], "children": [], "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:results:design-and-causal-inputs:part-0", "value": "##### Design and causal inputs"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:design-and-causal-inputs:part-1", "value": "The network has a 48-to-32 encoder, two genuine Puffer minGRU layers with 32 states each, and two action means. Recurrent, direct measurement and physical-product readouts combine within the same actor. The direct path preserves fast force response alongside the recurrent history."}, {"kind": "figure", "id": "inertial:unified_recurrent_control_band10_v3", "title": "One shared recurrent controller and its causal signal paths", "caption": "Two outputs share one history. The hard robot gate, issued-command queue, current regulation and physical limits remain explicit.", "queryId": "rl_method_contract", "asset": "figure27"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:design-and-causal-inputs:part-2", "value": "The observation contains 40 values; eight products are derived inside the policy. Fixed centering/scaling comes from engineering ranges and is stored with the weights."}, {"kind": "table", "id": "report:nested:results:learned-control-policy:results:design-and-causal-inputs:table-1", "title": "Design and causal inputs · Learned control policy", "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "headers": ["Input group", "External values", "What the policy receives"], "rows": [{"column0": "Force reconstruction", "column1": "3", "column2": "Normal, axial and lateral force from synchronized load-cell and downstream S-inertia measurements."}, {"column0": "Tool motion and geometry", "column1": "6", "column2": "Measured S acceleration in two modeled directions, S–A position, observed relative velocity, estimated actuator travel and estimated local slope."}, {"column0": "Commands, guard and recenter history", "column1": "9", "column2": "Present/aligned predictions from issued robot commands; issued current, total robot velocity and correction; gate readiness; recenter error."}, {"column0": "Known or identified context", "column1": "21", "column2": "Target, masses, orientation, spring/damper and coil parameters, electrical/travel limits, equilibrium current and acquisition/robot timing."}, {"column0": "Robot clock", "column1": "1", "column2": "The current 100 Hz decision phase. Absolute episode time and bump timing are absent."}, {"column0": "Derived features inside the policy", "column1": "8 additional", "column2": "Mass-conditioned acceleration, S–B interactions, force geometry, issued robot acceleration, damping × velocity and stiffness × travel error."}], "rightAligned": [false, true, false]}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:design-and-causal-inputs:part-3", "value": "Inference uses the causal observation port and identified context. True force and hidden states feed scoring/rewards. Surface profile and future motion stay outside inference; prediction uses commands already issued, including queued commands.\n\nThe minGRU state is carried between decisions and across rollout/chunk boundaries. It resets at a new physical episode. Closing the robot gate preserves both the neural history and commands already in flight. The initial paired filters span 0.1, 0.4, 3 and 20 ms; their weights and update gates can change during learning.\n\nThe two latent means are mapped to full requests as follows:\n\n- Current request: known static equilibrium current plus `2 A × tanh(current mean)`.\n- Robot correction request: `10 mm/s × tanh(robot mean)` at eligible 100 Hz events.\n\nThe experimental current replaces the dynamic force PI/feedforward command. Static equilibrium uses known weight/orientation and target; native current regulation and physical limits still apply. Robot force-stability/variation gates, dwell, delay-aware sign/amplitude envelope and velocity limits remain hard constraints. An ineligible update sends no new correction and cannot withdraw an issued command.\n\nTravel excursion beyond center ±7.5 mm is penalized. Some development cases intentionally start outside: report entry, time inside and maximum/final excess. Physical 0–25 mm stops remain failures. A stationary robot within the band is acceptable."}]}, {"id": "report:nested:results:learned-control-policy:results:initialization-and-learning", "title": "Initialization and learning", "depth": 5, "path": ["Results", "Learned control policy", "Results", "Initialization and learning"], "children": [], "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:results:initialization-and-learning:part-0", "value": "##### Initialization and learning"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:initialization-and-learning:part-1", "value": "Initialization uses a 0.1 A/N direct force gain and signed filter pairs cancelling their common startup component. Later probes initialized trainable recurrent/auxiliary connections with an approximate known spring/damper inverse. This disclosed physics prior remains within the actor's coefficients.\n\nPPO samples continuous latent actions and updates the actor from rewards and a value head. Discount/advantage constants use physical seconds. Contact/travel failures terminate; time limits bootstrap the final causal observation with cloned state. Robot losses use eligible 100 Hz actions. The stabilized critic detaches its gradient from the shared trunk to limit actor interference.\n\nEvolutionary reward search evaluates candidates in the native closed loop using reward, antithetic directions and covariance adaptation. There are no teacher actions or supervised labels. The band/history stage searched 55 coefficient directions; inverse refinement searches 37. The architecture stores 8,101 trainable parameters. These searches optimize constrained subspaces; PPO can update the full actor. The selected checkpoint and its ancestry are recorded with the results below. [PPO method](https://arxiv.org/abs/1707.06347), [evolutionary reward optimization](https://arxiv.org/abs/1703.03864), [minGRU architecture](https://arxiv.org/abs/2410.01201).\n\nWhole trajectories separate training, selection and final evaluation. Weights, source, native library, inputs, seeds and identities lock before fresh outcomes. Metrics include every native sample, startup and final sample. Failures/rejections remain retained. Assembled sanding performance requires measurement."}]}, {"id": "report:nested:results:learned-control-policy:results:completed-development-evidence", "title": "Completed development evidence", "depth": 5, "path": ["Results", "Learned control policy", "Results", "Completed development evidence"], "children": [], "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:results:completed-development-evidence:part-0", "value": "##### Completed development evidence"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:completed-development-evidence:part-1", "value": "One fixed band-search checkpoint, `48618b8d21c4f5920d870a05f5eb198c958632f51ffab6f0abfd6a8255ef0ad4`, was tested with its 64 learned states either carried normally or reset at every 100 µs decision. Both variants used identical weights, sensors, observers, plant, seeds and robot queues. TRAIN cases 0, 40, 96 and 139 produced eight complete recordings and 7,800,008 scored native samples. All eight passed the force requirement and avoided physical failure.\n\nThe force-peak changes were small and mixed. Carried/reset peaks were 0.10811/0.10832 N, 0.40415/0.40447 N, 0.15539/0.15087 N and 0.23457/0.23877 N. Travel showed a clearer history effect: TRAIN 96 spent 90.28%/51.59% of its recording inside the accepted band, and TRAIN 139 spent 82.71%/0%. The latter ended inside the band with carried state and 1.406 mm beyond it with resets. This is evidence that the learned history affects robot correction in these development cases. The reset variant retains the external causal observers and is not an independently optimized memoryless controller.\n\nThat checkpoint has 30 nonzero recurrent current-readout weights and 10 nonzero robot-readout weights, with L2 norms 0.784 and 4.285. Its band-search stage evolved 55 directions. The experiment isolates the effect of retaining this network's state."}, {"kind": "figure", "id": "inertial:memory_reliance_v2", "title": "Effect of carrying or resetting recurrent state", "caption": "Four development pairs using the same earlier gen5 weights. History helps stroke management; force-peak changes are small and mixed. This is not a newly optimized memoryless baseline.", "queryId": "rl_memory_reliance", "asset": "figure28"}]}, {"id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision", "title": "Native inference and numerical precision", "depth": 5, "path": ["Results", "Learned control policy", "Results", "Native inference and numerical precision"], "children": [], "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:part-0", "value": "##### Native inference and numerical precision"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:part-1", "value": "C inference carries 64 float32 states and emits action means/value. Its 8,181-float buffer holds parameters plus 80 normalization values, about 32.7 kB. CPU collection avoids per-tick GPU synchronization; the GPU performs PPO learning. Native recordings independently score force, electrical effort, travel and commands.\n\nAn inverse initialization with readout coefficients up to 662.1 amplified C/PyTorch state differences and cancellation error. Its first rollout showed a maximum current-request difference of 0.3155 mA and log-probability differences of 0.0356 on CUDA/0.0394 on CPU. Replay guards stopped that PPO continuation before an update. Both readout rounding and recurrent arithmetic contributed.\n\nFixed C closed-loop results retain their implementation/hashes. PPO needs verified behavior replay. Export acceptance must use the actual selected weights and arithmetic; compiler options and datatype are part of that contract.\n\nThe replay measurements are retained in `validation/rl_budget3h_20261005/runner_checks/inverse_replay_v1/results.json`; the four-case memory test is retained in `validation/rl_puffer_probe_20261005_final_driver_checks/memory_ablation_gen5/results.json`, both under `acf_simulink/`.\n\nThe unified recurrent controller learned useful current and robot actions, but **it did not qualify for deployment**. Its slightly better worst peak on the 700-case nominal grid did not transfer reliably to fresh conditions or prolonged motion. The deterministic controller remains the stronger prototype starting point; even that controller needs more margin and timing verification.\n\n**Question.** Can one history-based policy control the complete flange while maintaining workpiece-normal force within ±0.5 N and managing delayed robot recentering? The experiment used one shared, two-layer, 32-state Puffer minGRU with causal force, acceleration, relative position, identified parameters and already-issued robot commands. It received no future bump profile. Its two outputs commanded coil current and robot correction through the unchanged native current driver, stability gate, delay and limits. There was no dynamic PI force controller underneath the learned current action.\n\n**Training and selection.** Physics-informed initialization supplied force balance and causal filter features. Whole-episode evolutionary rewards adjusted successive compact parameter sets, including recurrent readouts; this was not teacher-action imitation or learning from a blank network. The stored network contains 8,101 trainable parameters, while individual evolutionary stages optimized 12, 28, 55, 41 or 37 degrees of freedom. These counts must not be confused.\n\nThe evolutionary lane completed 124 generations on the earlier sensor configuration and one generation after the budget-sensor change: **17,728 training episodes and 480,771,873 actor decisions**. The earlier stage executed 20,104 episodes including its selection and audit runs, plus 368 physics-initialization comparisons and 38 implementation checks; 21 evolutionary training episodes and three initialization comparisons physically failed. These counts exclude the separately recorded PPO experiments. The budget stage executed 616 scored episodes: 424 evolutionary training/selection/audit episodes, 136 bootstrap comparisons and 56 paired transfer-screen episodes. Five physical failures occurred in the latter two groups; the single budget evolutionary generation had none. Recovery replays remain separate from optimization counts.\n\nThe parallel PPO lane executed **1,372 updates, 15,824 minibatch steps and 124,368,632 actor decisions used by completed updates**. Its 5,130 completed training episodes included 38 physical failures in the early exploratory run. A further 98,304 collected decisions were rejected before an update by a C/PyTorch behavior-replay check and are counted separately. Stable PPO runs lowered RMS error while worsening the worst selection peak; none displaced the reward-search winner. On this machine, an actual PPO-update benchmark was **0.555 s on CPU versus 0.184 s on the RTX 3090 including transfer**, approximately **3.02× faster**. Native physical simulation remained on CPU; this is not a claim of a 3× whole-study speedup.\n\nThe final budget winner was the reward-selected `history_0p5` attenuation of previously evolved current-history weights. It did **not** receive the final budget evolutionary update. Its direct budget evidence before locking was **20 training cases plus all 28 selection cases**, all passing, with 0.454059 N selection worst error. Other candidates' 84-case audits do not belong to this checkpoint. The checkpoint was frozen before final testing, and neither weights nor selection were changed after seeing those results."}, {"kind": "figure", "id": "inertial:development_convergence", "title": "Development convergence; the earlier stages use the faster reference sensing chain.", "caption": "*Final results.*", "queryId": "rl_reward_search", "asset": "figure29"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:part-2", "value": "All force scores include startup and every native integration sample. A pass requires completing the recording without a physical stop while remaining within ±0.5 N. The ±7.5 mm travel band is reported separately as the user's preferred operating region; crossing it is different from reaching the physical ±12.5 mm stop."}, {"kind": "table", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:table-1", "title": "Native inference and numerical precision · Learned control policy", "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "headers": ["Final cohort", "Deterministic passes; worst force error", "Learned passes; worst force error", "Entire recording inside ±7.5 mm, deterministic / learned"], "rows": [{"column0": "700 nominal grid cases", "column1": "700/700; 0.428526 N", "column2": "700/700; 0.418410 N", "column3": "700/700 / 700/700"}, {"column0": "32 fresh cases", "column1": "32/32; 0.483324 N", "column2": "30/32; 0.678521 N", "column3": "32/32 / 32/32"}, {"column0": "Four 30 s cases", "column1": "4/4; 0.492243 N", "column2": "3/4; 0.489666 N before termination", "column3": "2/4 / 2/4"}], "rightAligned": [false, true, true, true]}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:part-3", "value": "These are **1,472 scored recordings (736 baseline/policy pairs) and 1,005,340,754 native sample points**. Nine additional native replay recordings, including a reproduced travel-stop failure, are excluded from those unique evaluation counts. The 700-case nominal grid checks parameter coverage; it does not replace the distinct fresh-condition and long-duration tests.\n\nThe nominal peak improvement was only 0.010116 N. Mean per-recording RMS error increased from 0.016068 N to 0.040781 N. On fresh cases it increased from 0.027376 N to 0.048349 N. Fresh case 86, at 33 N, S=1.1 kg and 50°, reached 0.678521 N; case 94 also exceeded the limit at 0.501417 N. Neither failure involved contact loss or a travel stop."}, {"kind": "figure", "id": "inertial:rl_3h_fresh_pairs", "title": "Paired fresh-case force results.", "caption": "", "queryId": "rl_fresh_tests", "asset": "figure30"}, {"kind": "figure", "id": "inertial:rl_3h_worst_force", "title": "The worst fresh force recording.", "caption": "", "queryId": "rl_fresh_tests", "asset": "figure31"}, {"kind": "figure", "id": "inertial:rl_3h_nominal_grid", "title": "The separate 700-case nominal grid.", "caption": "", "queryId": "rl_nominal_grid", "asset": "figure32"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:part-4", "value": "In the long 50 N, S=2 kg, 90° case, the learned controller reached the travel stop at **19.13094 s**. Its force remained below 0.5 N until termination, which does not make the recording a pass. The deterministic controller completed all four long recordings but exceeded the preferred travel band in two, reaching 9.028 mm from center. Its worst force reserve was just **0.007757 N**. Neither result supports a claim of comfortable long-duration robustness. There were no software rejections or robot request-clock/gate violations in the final cohorts; obeying the gate alone does not guarantee sufficient recentering."}, {"kind": "figure", "id": "inertial:rl_3h_robot_travel", "title": "Robot travel relative to the preferred band.", "caption": "", "queryId": "rl_fresh_tests", "asset": "figure33"}, {"kind": "figure", "id": "inertial:rl_3h_long_stop", "title": "The learned controller's long-run physical stop.", "caption": "*Performance limits.*", "queryId": "rl_long_tests", "asset": "figure34"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:part-5", "value": "Two additional locked-policy development screens each ran the same 28 cases with both controllers: 112 scored episodes and 3,658,783 actor decisions, with two recovery replays counted separately. They did not alter the final winner."}, {"kind": "table", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:table-2", "title": "Native inference and numerical precision · Learned control policy", "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "headers": ["Budget-chain development condition", "Deterministic passes; worst error", "Learned passes; worst error"], "rows": [{"column0": "50 µs current response, declared sensing timing", "column1": "28/28; 0.463682 N", "column2": "28/28; 0.454059 N"}, {"column0": "100 µs current response", "column1": "28/28; 0.493979 N", "column2": "26/28; 0.640529 N"}, {"column0": "50 µs current response plus known, matched 50 µs sensing delay", "column1": "26/28; 0.513855 N", "column2": "15/28; 1.129700 N"}], "rightAligned": [false, true, true]}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:part-6", "value": "The learned policy also suffered one physical stop with the slower current response and two with added sensing delay. The 100 µs condition's worst force case had **no voltage clipping**, so a higher supply voltage at unchanged current-loop tuning cannot explain away that failure. Added latency remained harmful even when known and matched in identification. These experiments identify current-loop response and synchronized sensor phase as concrete constraints; voltage headroom is only one part of the problem."}, {"kind": "figure", "id": "inertial:rl_3h_drive", "title": "Recorded drive effort and clipping.", "caption": "", "queryId": "rl_fresh_tests", "asset": "figure35"}, {"kind": "figure", "id": "inertial:budget_response_limits", "title": "Paired budget current-response and latency limits.", "caption": "*Independent implementation checks.** The selected checkpoint's regenerated C source, header, flat weights, layout and arrays match byte for byte; all three cohort launchers verify their locked sources. Two independent normal MATLAB replays then consume the saved requests for fresh cases 86 and 95. Each scores all **1,800,001 samples over 6 s** and exactly reproduces its compiled-run force peak. Across all 27 diagnostic channels, the largest difference is **5.33 × 10⁻¹⁴*", "queryId": "rl_budget_response_limits", "asset": "figure36"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:results:native-inference-and-numerical-precision:part-7", "value": ", with identical timestamps and no algebraic loops. The 0.678521 N force failure is reproduced. These are plant/sensor/gate replays using recorded actions; they do not substitute MATLAB or PyTorch neural arithmetic for the frozen C actor.\n\n\nHalving the plant integration step from **3.333 to 1.667 µs**, while preserving the original noise, ADC, actor and robot clocks and replaying the same requests, gives **3,600,001 points**. The worst-case peak changes from **0.678521230 to 0.678507391 N**, a reduction of only **0.000013838 N**; its peak time stays 1.230410 s. The force requirement still fails. This checks recorded-action plant sensitivity, **not closed-loop neural inference with refined feedback states**. No learned branch is promoted on this evidence."}]}], "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:results:part-0", "value": "#### Results"}]}, {"id": "report:nested:results:learned-control-policy:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Learned control policy", "Recommendation"], "children": [], "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:learned-control-policy:recommendation:part-1", "value": "**Recommendation.** Build the budget prototype around the deterministic measured-inertia controller, using the voice coil, upper rigid link and lower opposed spring pair. Retain approximately 19.7 kN/m combined stiffness and 60 N·s/m external damping, and identify the assembled mechanics for each tool. The approximate spring packing remains comfortably within the 100 mm spring-only condition.\n\nUse the budget accelerometer/ADC chain as a **conditional prototype target**: ADXL354-class acceleration sensing, ADS131M08 acquisition at 30 ksample/s, matched 1.9 kHz response envelopes, synchronized force/acceleration measurements and a 10 kHz controller. Target the tested 50 µs current response with at least 32 V usable bipolar output from the proposed 36 V supply. Verify these response and timing figures on the assembled hardware, including filtering, ADC delay, driver phase, calibration and noise; nominal sample rate alone is insufficient.\n\nBefore sanding trials, improve and validate sustained robot recentering and establish more force margin than the 0.007757 N long-case reserve. Check thermal operation and structural modes under real sanding vibration. Keep the neural policy as a reproducible research candidate with its failures intact. **Do not deploy it as the flange controller on the evidence obtained here.**\n\n\nThe saved checkpoint, C inference, normalization, exact feature order and locked physics are under `acf_simulink/validation/rl_budget3h_20261005/selected_controller/`. To reproduce the paired 32-case test from the repository root, run:\n\n```bash\n/home/tommie/Pesten/puffer4-native/.venv/bin/python acf_simulink/experiments/rl_budget3h_20261005/run_saved_policy.py --cohort holdout32\n```\n\nUse `--cohort nominal700` or `--cohort long4` for the other retained tests, and `--dry-run` to verify all source and bank hashes without simulating. The [run guide](/home/tommie/Projects/actuator-model/acf_simulink/experiments/rl_budget3h_20261005/README.md) explains the package and resource needs. The public Simulink model continues to expose the deterministic scientific-reference controller; the research checkpoint has not been promoted into its diagram."}]}], "queryIds": ["rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:learned-control-policy:part-0", "value": "### Learned control policy"}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation", "title": "Calibration, model qualification and prototype validation", "depth": 3, "path": ["Results", "Calibration, model qualification and prototype validation"], "children": [{"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:intro", "title": "Intro", "depth": 4, "path": ["Results", "Calibration, model qualification and prototype validation", "Intro"], "children": [], "queryIds": ["qualified_range", "actual_mechanics_tolerance", "final_acquisition_endpoints", "final_worst_excerpt", "mixed_mechanics_identification", "final_solver_refinement", "mixed_static_calibration", "final_sensing_OAT", "final_robot_OAT", "final_joint_budget", "joint_budget_plan", "final_long_joint_budget", "final_static_calibration_long", "static_calibration_comparison", "budget_adc_range", "budget_sensing_execution"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:intro:part-0", "value": "#### Intro"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:intro:part-1", "value": "Native simulation supports a design choice only within its recorded model, metric, inputs and test identities. Calibration residuals, mechanical identification and physical validation consume reserve beyond nominal noise."}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:question", "title": "Question", "depth": 4, "path": ["Results", "Calibration, model qualification and prototype validation", "Question"], "children": [], "queryIds": ["qualified_range", "actual_mechanics_tolerance", "final_acquisition_endpoints", "final_worst_excerpt", "mixed_mechanics_identification", "final_solver_refinement", "mixed_static_calibration", "final_sensing_OAT", "final_robot_OAT", "final_joint_budget", "joint_budget_plan", "final_long_joint_budget", "final_static_calibration_long", "static_calibration_comparison", "budget_adc_range", "budget_sensing_execution"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:question:part-0", "value": "#### Question"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:question:part-1", "value": "What has actually passed, how much margin remains under mismatch, and what must be measured before claiming ±0.5 N on the powered physical prototype?"}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results", "title": "Results", "depth": 4, "path": ["Results", "Calibration, model qualification and prototype validation", "Results"], "children": [{"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:full-scientific-reference-grid-and-numerical-qualification", "title": "Full scientific-reference grid and numerical qualification", "depth": 5, "path": ["Results", "Calibration, model qualification and prototype validation", "Results", "Full scientific-reference grid and numerical qualification"], "children": [], "queryIds": ["qualified_range", "final_acquisition_endpoints", "final_worst_excerpt", "final_solver_refinement"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:full-scientific-reference-grid-and-numerical-qualification:part-0", "value": "##### Full scientific-reference grid and numerical qualification"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:full-scientific-reference-grid-and-numerical-qualification:part-1", "value": "The frozen scientific-reference system retains the soft lower link and causal inverse, and uses the explicit 100 ksample/s matched acquisition graph, the 10 kHz controller and the fast force-variation gate. Nine complete 10 s endpoint recordings pass, including a clean heavy-tool reference and noisy light/heavy endpoints. Their worst normal-force error is **0.32242 N**. A separate two-seed repeated-heavy drive study, discussed below, reaches **0.34532 N** at the same selected 100 µs current response. Noise seeds and test cohorts differ; each quoted maximum belongs to its recorded cohort.\n\nThe broad nominal grid covers five S masses (0.1, 0.5, 1, 1.4 and 2 kg), ten force targets (5–50 N in 5 N increments), seven fixed orientations (0–90° in 15° increments), two physical drag ratios (0 and 0.3), and one clean plus four noisy conditions. **All 3,500 unique four-second cases pass**, with all **400,001 native samples per case** scored, including startup: **1,400,003,500 force samples in total**. The coverage audit finds no missing or duplicate identities and verifies all 700 common five-seed groups. The worst error is **0.315811 N**, leaving **0.184189 N** inside the ±0.5 N band. It occurs with S=2 kg, 50 N, 75°, drag ratio 0.3 and seed 97, at 2.00063 s. This qualifies the specified finite nominal grid; the calibration and physical-parameter screens have their own narrower scopes.\n\nThe worst errors at S=0.1, 0.5, 1, 1.4 and 2 kg are respectively **0.1033, 0.1096, 0.1719, 0.2295 and 0.3158 N**. Across the grid, the generic winding reaches **2.9466 A and 19.5489 V**, without current/voltage clipping, contact loss or a travel stop. The fixed 33.6 N preload passes every case, with a common feasible interval of **30.374–40.637 N per spring**, 40.98 mm conservative combined free length and 34.174 mm combined installed length. The largest normal-force balance residual is 2.84×10⁻¹⁴ N.\n\nThe four interleaved partitions use one immutable scientific model, candidate and helper set. Their two execution recipes differ only in temporary simulation-data storage: 1,060 validated disk-backed recordings are reused once, and 2,440 remaining identities use private RAM-backed storage after a full-channel parity proof. The 122 earlier recovery recordings remain separate from the 3,500 unique cases. The case CSV, complete coverage audit and retained worst native history are in `validation/normal_mass_controller_final_grid_20260930_*`."}, {"kind": "figure", "id": "inertial:inertial_final_range_coverage", "title": "Full nominal force, orientation and tool-mass qualification", "caption": "3,500 completed native recordings. Each cell shows the worst complete-history error over both drag ratios and all five clean/noisy conditions. All masses have 700 recordings; the common color scale ends at the ±0.5 N limit.", "queryId": "qualified_range", "asset": "figure37"}, {"kind": "figure", "id": "inertial:inertial_final_worst_native", "title": "Native worst case from the complete nominal grid", "caption": "The retained global worst recording: S=2 kg, 50 N, 75°, drag ratio 0.3, seed 97. Every 10 µs sample in the plotted window is shown; all 400,001 samples determine the metric. The 100 Hz robot gate remains ready here because its filtered stability criteria remain satisfied.", "queryId": "final_worst_excerpt", "asset": "figure38"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:full-scientific-reference-grid-and-numerical-qualification:part-2", "value": "Rerunning this exact worst identity at **5 and 2.5 µs** gives peak errors of **0.315822976 and 0.315825399 N**, compared with 0.315810929 N at 10 µs. The finer difference is only **2.42 µN**, and the total change from the working step is **14.47 µN**. Both refined histories pass force, spring packing, contact and travel checks without clipping. All 72 physical/control channels are compared on their own sample grids; the four robot-gate channels remain at their actual 100 Hz rate. Raw acquisition, controller periods, noise and physical inputs are unchanged. This supports the 10 µs working step for this final candidate and worst nominal case."}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:random-noise-fixed-offsets-and-what-is-not-injected", "title": "Random noise, fixed offsets and what is not injected", "depth": 5, "path": ["Results", "Calibration, model qualification and prototype validation", "Results", "Random noise, fixed offsets and what is not injected"], "children": [], "queryIds": ["joint_budget_plan", "budget_adc_electrical", "budget_sensing_robustness"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:random-noise-fixed-offsets-and-what-is-not-injected:part-0", "value": "##### Random noise, fixed offsets and what is not injected"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:random-noise-fixed-offsets-and-what-is-not-injected:part-1", "value": "The nominal 700-case lower-cost grid includes sensor noise, converter noise and explicit quantization, with zero residual static calibration errors. The selected long/mixed stress cases add the tighter fixed biases, gains, alignment and identified-parameter errors. These selected corners do not exhaust the complete error box."}, {"kind": "table", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:random-noise-fixed-offsets-and-what-is-not-injected:table-1", "title": "Random noise, fixed offsets and what is not injected · Calibration, model qualification and prototype validation", "queryIds": ["joint_budget_plan", "budget_adc_electrical", "budget_sensing_robustness"], "headers": ["Measurement", "Original reference-conditioned sensor noise, RMS", "Fixed residual zero in selected stress cases"], "rows": [{"column0": "Force, each used axis", "column1": "0.02 N", "column2": "±0.01 N"}, {"column0": "S acceleration, each used axis", "column1": "0.014 m/s²", "column2": "±0.005 m/s²"}, {"column0": "S–A position", "column1": "1 µm", "column2": "No independent position-zero error stressed"}], "rightAligned": [false, true, true]}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:random-noise-fixed-offsets-and-what-is-not-injected:part-2", "value": "Force and position noise start as bounded uniform noise; acceleration noise is Gaussian. Input noise density is fixed when changing conditioning or sample rate, so the listed conditioned RMS values are not constant at every bandwidth. Converter noise is added separately before smoothing and explicit quantization; the selected M08 reference-acceleration chain uses approximately **0.00284 N force noise** and **0.01045 m/s² acceleration noise**, RMS at that injection point. Position uses a separate encoder. These contributions cannot be added directly without their transfer functions.\n\nThe fixed residual biases remain constant during each recording. The studies do not provide measured powered-sander vibration, vibration rectification, evolving thermal drift, random sampling jitter or switching-current ripple. Those need assembled measurements."}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:executed-calibration-and-timing-mismatch", "title": "Executed calibration and timing mismatch", "depth": 5, "path": ["Results", "Calibration, model qualification and prototype validation", "Results", "Executed calibration and timing mismatch"], "children": [], "queryIds": ["final_sensing_OAT", "final_robot_OAT", "final_joint_budget", "joint_budget_plan", "final_long_joint_budget", "final_static_calibration_long", "static_calibration_comparison"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:executed-calibration-and-timing-mismatch:part-0", "value": "##### Executed calibration and timing mismatch"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:executed-calibration-and-timing-mismatch:part-1", "value": "The sensor requirement is a calibrated, synchronized measurement chain. ADC bit count, catalog resolution and sample rate are only parts of that chain. The completed final-source calibration work includes **42 sensing one-at-a-time recordings**, **14 robot-response recordings**, and **60 simultaneous-error recordings**. All 116 meet the force band in their declared cohorts. Six separate native endpoint/parity records verify that the instrumentation and Accelerator runner preserve the complete 72 logged channels bitwise; they are software proofs rather than extra uncertainty cases.\n\nThe joint sample uses two operating endpoints: S=2 kg, 50 N, 90°, and S=0.1 kg, 5 N, 0°. Each has three noise seeds and ten deterministic sign corners. Twenty-six declared residual errors change together. Each recording lasts four seconds. The worst is **0.44809 N**, leaving **0.05191 N** to the limit, at the heavy endpoint with seed 7 and corner 8. All recordings complete without clipping, contact loss or a travel stop, and the actual 33.6 N preload passes their 20 mm spring packing checks. This finite corner sample does not prove every combination inside a 26-dimensional error box or every mass/force/orientation under those simultaneous errors.\n\nFour **30 s repeats**, each crossing **24 sharp bumps**, extend the difficult joint corners: three heavy corner-8 seeds and one light corner-3 seed. All four pass every one of their **3,000,001 native samples**, including startup, without clipping or physical stops. Heavy worst errors are **0.488090, 0.487071 and 0.490396 N**; the light case reaches **0.086891 N**. The heavy seed-1729 maximum occurs **0.690 ms into the tenth bump**, at 12.80069 s. It leaves only **0.009604 N** reserve, despite the substantial nominal-grid margin.\n\nThe heavy repeats also show a sustained true-force offset of approximately **+0.147–0.148 N** while the feedback holds its own reconstructed force near target. Calibration errors therefore consume substantial reserve before the sharp transient arrives. The values below are tested outer stress limits, rather than a desirable routine operating point. A tare removes zero/gravity offset but cannot by itself correct load gain, cross-axis coupling or response mismatch."}, {"kind": "table", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:executed-calibration-and-timing-mismatch:table-1", "title": "Executed calibration and timing mismatch · Calibration, model qualification and prototype validation", "queryIds": ["final_sensing_OAT", "final_robot_OAT", "final_joint_budget", "joint_budget_plan", "final_long_joint_budget", "final_static_calibration_long", "static_calibration_comparison"], "headers": ["Measurement or identified quantity", "Tested outer stress budget", "Selected calibration/noise target", "Design meaning"], "rows": [{"column0": "Force, each used axis", "column1": "±0.02 N zero, ±0.1% reading gain", "column2": "**±0.01 N zero, ±0.05% gain**; same 0.02 N conditioned RMS noise", "column3": "Calibrate the operating force range and gravity tare; factory full-scale accuracy alone is insufficient"}, {"column0": "Force cross-axis coupling", "column1": "±0.1% residual per tested direction", "column2": "**±0.05%**", "column3": "Calibrate the matrix under representative axial/lateral loads"}, {"column0": "Force and accelerometer frame", "column1": "±0.1° residual alignment each", "column2": "**±0.05° each**", "column3": "Align sensor axes to flange coordinates and confirm tare consistency"}, {"column0": "S acceleration", "column1": "±0.01 m/s² bias, ±0.5% scale", "column2": "**±0.005 m/s² bias, ±0.25% scale**; same 0.014 m/s² conditioned RMS", "column3": "About 0.51 mg bias; verify thermal drift and powered-tool vibration"}, {"column0": "Known downstream S mass", "column1": "±0.5% identified residual", "column2": "**±0.25%**, about ±5 g at S=2 kg", "column3": "Include everything beyond the cell and use tool-specific identification"}, {"column0": "Holder B and force constant", "column1": "±0.5% identified residual each", "column2": "**±0.25% each**", "column3": "Partition moving masses and map calibrated Kf over the used stroke/temperature"}, {"column0": "S-relative-A position", "column1": "±0.1% scale residual", "column2": "**±0.05% scale**; same 1 µm conditioned RMS", "column3": "Synchronize the relative sensor; count size is not complete accuracy"}, {"column0": "Commanded scan speed", "column1": "±0.1% identified residual", "column2": "**±0.05%**", "column3": "Use actual issued tangential motion and its timestamp"}, {"column0": "Analog response matching", "column1": "Common cutoff ±5%; other axes ±5% relative to force", "column2": "Same tested mismatch; identify complex response", "column3": "Pairwise cutoff difference can reach 10% of common cutoff; this was unchanged in the refinement"}, {"column0": "Acquisition timing", "column1": "Common 20 µs pipeline ±10 µs; other used channels ±10 µs relative", "column2": "Same tested mismatch, common clock", "column3": "Actual delays span 0–40 µs; this was unchanged in the refinement"}, {"column0": "Robot prediction", "column1": "Actual 80 ms delay ±5 ms and 60 ms response ±5 ms", "column2": "Same **±5 ms** residual targets", "column3": "Identify loaded response, retain pending commands and check timing"}], "rightAligned": [false, false, false, false]}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:executed-calibration-and-timing-mismatch:part-2", "value": "These budgets are **residuals after calibration**, not guaranteed out-of-box specifications or interchangeable independent allowances. The joint test holds mechanical k/c nominal; the ±20% physical mechanical study is separate. A fixed delay mismatch is also different from random latency jitter. Known actual k/c does not remove the persistent sensor-calibration offset in these nominal-mechanics repeats.\n\nThe selected static targets receive a direct **four-record, 30 s paired refinement**. Only sixteen bias, gain, alignment and identification residuals are halved; noise, analog/pipeline mismatch, robot delay/response, actual mechanics, current response and PI settings remain unchanged. All four new records pass their full native histories. The heavy three peaks become **0.411872, 0.411243 and 0.415311 N**, and the light peak **0.075628 N**. The worst reserve increases from **0.009604 to 0.084689 N**, recovering **0.075085 N**. Sustained heavy force offset falls to approximately **+0.073–0.074 N**.\n\nThis is evidence that static calibration can recover useful reserve without a faster or noisier controller. It qualifies those four declared repeats, rather than the whole tighter error box or every nominal grid point with simultaneous residuals. The tighter targets need warm known-load/axis-matrix calibration, accurate mass measurements and tool-specific Kf identification; they are requirements to verify on assembled hardware. The manufacturer examples are plausible measurement-chain starting points, rather than guarantees of those residuals."}, {"kind": "figure", "id": "inertial:inertial_calibration_refinement", "title": "Tighter calibration recovers margin through repeated sharp bumps", "caption": "The same four 30 s corner cases before and after sixteen static residuals are halved. Every 3,000,001-sample history determines its metric; the lower histories use all-native min/max bins. Noise, analog response, pipeline, robot timing, actual mechanics and current response remain unchanged.", "queryId": "static_calibration_comparison", "asset": "figure39"}, {"kind": "figure", "id": "inertial:inertial_uncertainty_v8_sensing", "title": "Final sensing and robot-response sensitivity", "caption": "42 native sensing records. Each entry reports its own tested worst full-history force error; it is not an independently additive budget.", "queryId": "final_sensing_OAT", "asset": "figure40"}, {"kind": "figure", "id": "inertial:inertial_uncertainty_v8_joint", "title": "Simultaneous calibration errors at the two declared endpoints", "caption": "60 native records, ten deterministic 26-dimensional corners, three seeds at each endpoint. The full ±0.5 N band includes startup and every bump sample.", "queryId": "final_joint_budget", "asset": "figure41"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:executed-calibration-and-timing-mismatch:part-3", "value": "The ATI Mini27-class cell's published force resolution and full-scale accuracy do not establish the required 0.02 N conditioned noise or selected ±0.01 N residual zero. A TWE/raw bridge interface with calibrated conditioning is the reference route for controlling the complete chain; a turnkey low-rate digital interface is not automatically an equivalent substitution. The faster reference uses two ADXL1002-class axes; the budget prototype uses two axes of one ADXL354C on S. Use a simultaneous ADC/clock for force and acceleration, and timestamp the relative-position counter to that same frame. If all six raw bridge channels and two acceleration axes are acquired, an eight-channel simultaneous ADC fits that analog count; the position counter is separate.\n\nMount the accelerometer on the rigid downstream assembly so it represents the modeled mass acceleration. Tool rotation, pad flexure or an orbital mechanism can make acceleration at the sensor differ from the assembly center-of-mass acceleration; this model does not supply that correction. Test the powered sanding tool under real vibration, with the complete antialias chain. A white-noise pass is not a vibration or aliasing guarantee.\n\nA useful physical validation separates three measurements: static force calibration over the intended force/orientation range, a dynamic response/phase measurement of force versus acceleration, and an independent contact-force reference while running the bump. Verify current-loop response under the hot winding, low-friction motion, assembled mounting modes and loaded robot response before claiming the simulated margin on hardware."}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:model-limitations-and-disturbance-scope", "title": "Model limitations and disturbance scope", "depth": 5, "path": ["Results", "Calibration, model qualification and prototype validation", "Results", "Model limitations and disturbance scope"], "children": [], "queryIds": ["qualified_range", "actual_mechanics_tolerance", "final_acquisition_endpoints", "final_worst_excerpt", "mixed_mechanics_identification", "final_solver_refinement", "mixed_static_calibration", "final_sensing_OAT", "final_robot_OAT", "final_joint_budget", "joint_budget_plan", "final_long_joint_budget", "final_static_calibration_long", "static_calibration_comparison", "budget_adc_range", "budget_sensing_execution"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:model-limitations-and-disturbance-scope:part-0", "value": "##### Model limitations and disturbance scope"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:model-limitations-and-disturbance-scope:part-1", "value": "The model calculates force balances, explicit rigid constraints, spring/damper loads, stroke, actuator current and voltage, sensor filtering/noise/delay, causal estimation, fast force control and slow delayed robot recentering. It can reject a proposed spring pack for its working travel and combined length, and it can identify whether a recording fails because of force error, contact loss, travel exhaustion, current limit or drive voltage.\n\nIt represents translational point contact in a scanning plane. A real sanding pad distributes pressure over an area and deforms. Local surface shape, pad compliance, rotations, moments, abrasive removal and spatially varying friction can change the relationship between tool motion and the local surface normal. The guides and robot must carry lateral force and moments without introducing unmodeled motion. Tool vibration and accelerometer vibration rectification are not supplied by the bump waveform.\n\nThe qualified bump is the specified **C² polynomial profile**: height, velocity and acceleration are continuous, with finite jerk jumps at entry and exit. Height, width and speed alone do not specify disturbance severity. As an analytical comparison, a half-cosine bump of the same dimensions has an approximately **1.974 m/s² acceleration jump** at entry, equivalent to **3.95 N of S inertia at 2 kg**. A continuous spring/damper force and finite current response cannot instantly cancel an unpreviewed jump. This comparison adds no simulation qualification; sharper edges need their own tests and realistic pad/contact compliance. Extra voltage does not remove the causal limitation.\n\nElectrical winding dynamics and voltage clipping are retained, but winding temperature is a separately calculated operating constraint until thermal dynamics and force-constant drift are measured. Coil geometry, position dependence, cable forces, bearing stiction, backlash and whole-flange packaging require prototype characterization. A 100 mm spring allowance is not a 100 mm envelope for the actuator, guides, sensor and sanding head together.\n\nEach run starts at a loaded equilibrium with known or calibrated tool mass and fixed orientation. A finite parameter/noise grid establishes performance on its recorded cases; it does not prove every possible disturbance, every noise realization or a continuously rotating operating trajectory. Numerical qualification is evidence for choosing and testing a prototype, rather than a substitute for testing one."}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:running-changing-and-reproducing-the-native-model", "title": "Running, changing and reproducing the native model", "depth": 5, "path": ["Results", "Calibration, model qualification and prototype validation", "Results", "Running, changing and reproducing the native model"], "children": [], "queryIds": ["qualified_range", "actual_mechanics_tolerance", "final_acquisition_endpoints", "final_worst_excerpt", "mixed_mechanics_identification", "final_solver_refinement", "mixed_static_calibration", "final_sensing_OAT", "final_robot_OAT", "final_joint_budget", "joint_budget_plan", "final_long_joint_budget", "final_static_calibration_long", "static_calibration_comparison", "budget_adc_range", "budget_sensing_execution"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:running-changing-and-reproducing-the-native-model:part-0", "value": "##### Running, changing and reproducing the native model"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:running-changing-and-reproducing-the-native-model:part-1", "value": "Open the saved diagram with `addpath('acf_simulink'); mdl = acf_open;` from the project folder in MATLAB. The root **Actuator selection** chooses coil or leadscrew; **Force controller selection** chooses Feedforward PI, PI or PID. The green Run button uses structure **p in the Model Workspace**, so the physical diagram remains the leading model. The [getting-started guide](/home/tommie/Projects/actuator-model/acf_simulink/GETTING_STARTED.md) shows the parameter editor, controller gain fields, removed-spring preset and the exact slow-bump example with B+S=2 kg. That slow example completes with **0.07328 N** worst force error. The [13-page native diagram PDF](/home/tommie/Projects/actuator-model/acf_simulink/generated/active_flange_native_model_pages_20260930.pdf) lets you inspect the blocks without opening MATLAB.\n\nThe delivered model uses ordinary native blocks and shallow subsystems, with separate physical drive, force reconstruction, motion observer, fast controller and delayed robot paths. Private acceptance checks establish source-history parity, direct Run after parameter edits, both physical failure stops and save/reopen behavior. The public diagram removes 33 unused wire stubs while preserving all connected edges and parameter values. Preserve any unsaved edits before reopening a model already loaded in the desktop.\n\nFor repeated studies, use Accelerator mode, reuse valid compilation and clear simulation-data history after scoring each case. Temporary SDI logging was a substantial bottleneck. A paired four-case pilot compared private disk and RAM-backed SDI storage with bitwise equality across all 72 channels: median warm ten-second execution fell from **39.78 to 6.81 s**, about **5.84×** under the recorded concurrent load. Final workers typically completed a four-second simulation in roughly **2–2.8 s warm**. These are host/load-specific timings, not cold-start or UI timings. The physical model and 10 µs working step stayed unchanged.\n\nThe [reproduction guide](/home/tommie/Projects/actuator-model/acf_simulink/REPRODUCING_RESULTS.md) identifies the immutable scientific source, candidate, two exact grid recipes, calibration/actuator studies, execution checks and portable input snapshots. Metrics always use full native histories before plot reduction. The offline HTML report supports source inspection and filtering of all 3,500 cases; the separate replay preserves the worst native force sample. Historical studies and interrupted/software-rejected attempts remain recorded separately from completed physical cases."}]}], "queryIds": ["qualified_range", "actual_mechanics_tolerance", "final_acquisition_endpoints", "final_worst_excerpt", "mixed_mechanics_identification", "final_solver_refinement", "mixed_static_calibration", "final_sensing_OAT", "final_robot_OAT", "final_joint_budget", "joint_budget_plan", "final_long_joint_budget", "final_static_calibration_long", "static_calibration_comparison", "budget_adc_range", "budget_sensing_execution"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:results:part-0", "value": "#### Results"}]}, {"id": "report:nested:results:calibration-model-qualification-and-prototype-validation:recommendation", "title": "Recommendation", "depth": 4, "path": ["Results", "Calibration, model qualification and prototype validation", "Recommendation"], "children": [], "queryIds": ["qualified_range", "actual_mechanics_tolerance", "final_acquisition_endpoints", "final_worst_excerpt", "mixed_mechanics_identification", "final_solver_refinement", "mixed_static_calibration", "final_sensing_OAT", "final_robot_OAT", "final_joint_budget", "joint_budget_plan", "final_long_joint_budget", "final_static_calibration_long", "static_calibration_comparison", "budget_adc_range", "budget_sensing_execution"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:recommendation:part-0", "value": "#### Recommendation"}, {"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:recommendation:part-1", "value": "Use the **tighter post-calibration residuals**, identify each assembled tool/mechanism, and check force balance, response/phase, hot driver headroom and structural modes. The nominal 3,500-case reference grid and 700-case lower-cost grid have different frozen acquisition sources and noise cohorts; neither proves all combinations of mismatch or real sanding vibration. Keep the learned-policy test cohort distinct from those established baselines.\n\nValidate with an independent workpiece-force reference while the sander is powered and at operating temperature. The proposed physical criterion is **maximum absolute reference-force error plus applicable measurement uncertainty ≤0.45 N**, preferably with about **0.02 N or better reference uncertainty**. This is an acceptance target, not an observed hardware pass."}]}], "queryIds": ["qualified_range", "actual_mechanics_tolerance", "final_acquisition_endpoints", "final_worst_excerpt", "mixed_mechanics_identification", "final_solver_refinement", "mixed_static_calibration", "final_sensing_OAT", "final_robot_OAT", "final_joint_budget", "joint_budget_plan", "final_long_joint_budget", "final_static_calibration_long", "static_calibration_comparison", "budget_adc_range", "budget_sensing_execution"], "fragments": [{"kind": "prose", "id": "report:nested:results:calibration-model-qualification-and-prototype-validation:part-0", "value": "### Calibration, model qualification and prototype validation"}]}], "queryIds": ["qualified_range", "final_static_calibration_long", "budget_adc_range", "budget_adc_hot_coil", "budget_sensing_execution", "rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:results:part-0", "value": "## Results"}, {"kind": "prose", "id": "report:nested:results:part-1", "value": "**Scientific-reference result:** all 3,500 nominal sharp-bump cases pass, worst error **0.315811 N**. Four repeated 30 s stress cases with the selected static calibration pass at **0.415311 N** worst. The recommended prototype uses a voice coil, measured-inertia feedforward PI, a synchronized multi-axis load cell and S-mounted accelerometers, with assembled calibration and dynamic verification.\n\n**Lower-cost sensing update, 2 October:** the ADS131M08 at 30 ksample/s with a matched 8 kHz complete-response envelope passes all **700 new nominal conditions**, worst **0.292804 N**. Seven selected hot-coil long/mixed cases pass at **0.438821 N** worst. The 999-recording cost study supports reducing ADC cost while retaining the reference acceleration sensors; the cheaper sensor envelopes consume substantial margin or fail. These results have their own source, noise seeds and qualification scope.\n\n**Learning and €100 sensing update, 5 October:** one shared recurrent policy now controls full coil-current and robot requests. With the ADXL354C/M08 budget chain, both it and PI + feedforward pass the 700-case nominal grid. The locked neural policy then passes **30/32 fresh varied cases and 3/4 long cases**, with a **0.678521 N force error** and one travel stop. The deterministic baseline passes all **736 physical/force cases**, but its long worst is **0.492243 N** and two long cases leave the accepted ±7.5 mm travel band. Use that baseline for the affordable bench prototype; neither a robust hardware margin nor a deployment-ready neural controller is established."}]}, {"id": "report:nested:recommendation", "title": "Recommendation", "depth": 2, "path": ["Recommendation"], "children": [], "queryIds": ["selected_settings", "actual_mechanics_tolerance", "joint_budget_plan", "final_electrical", "acceleration_and_drive_parts", "coil_parts", "mixed_mechanics_identification", "full_grid_hot_headroom", "final_static_calibration_long", "mixed_static_calibration", "calibrated_hot_headroom", "budget_adc_parts", "budget_adc_range", "budget_adc_hot_coil", "budget_accelerometer_stress", "rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "fragments": [{"kind": "prose", "id": "report:nested:recommendation:part-0", "value": "## Recommendation"}, {"kind": "prose", "id": "report:nested:recommendation:part-1", "value": "Build the first prototype around a **guided voice coil, an upper rigid attachment, one lower opposed spring pair and a 60 N·s/m parallel damper**, using the **measured-inertia Feedforward PI** controller. Keep the B–S multi-axis cell in the complete lower load path, mount synchronized acceleration sensing on S and measure S relative to A. Identify the assembled spring/damper values for the inverse, rather than relying on catalog rates. Use the issued-command robot predictor with the force-stability/variation gate and delay-aware recentering gain cap."}, {"kind": "table", "id": "report:nested:recommendation:table-1", "title": "Recommendation", "queryIds": ["selected_settings", "actual_mechanics_tolerance", "joint_budget_plan", "final_electrical", "acceleration_and_drive_parts", "coil_parts", "mixed_mechanics_identification", "full_grid_hot_headroom", "final_static_calibration_long", "mixed_static_calibration", "calibrated_hot_headroom", "budget_adc_parts", "budget_adc_range", "budget_adc_hot_coil", "budget_accelerometer_stress", "rl_method_contract", "rl_budget_parts", "rl_budget_sensing_contract", "rl_ppo_training", "rl_reward_search", "rl_initialization_probes", "rl_budget_reward_search", "rl_selected_candidate", "rl_implementation_checks", "rl_fresh_tests", "rl_nominal_grid", "rl_long_tests", "rl_actuator_response", "rl_budget_response_limits", "rl_memory_reliance", "rl_gate_tradeoff", "rl_final_native_replay"], "headers": ["Subsystem", "Concrete starting specification"], "rows": [{"column0": "Lower spring pair", "column1": "Net 19.746 N/mm, approximately 9.873 N/mm each, about 20 mm free length each, 33.6 N preload each"}, {"column0": "Spring working envelope", "column1": "At least the modeled 68.54 N individual force envelope and 3.18 mm cyclic stroke; guided, no cell bypass"}, {"column0": "Parallel damping", "column1": "Approximately 60 N·s/m with low stiction; characterize at roughly 0–35 mm/s"}, {"column0": "Moving mass", "column1": "B budget 0.6 kg, interchangeable S=0.1–2 kg; include cell/tool-side attachments in the correct mass"}, {"column0": "Coil", "column1": "Approximately 20–25 N/A, preferably at least 65–70 N continuous **over the used stroke and at operating temperature**, 25 mm travel, bipolar drive"}, {"column0": "Electrical drive", "column1": "Start around R=4–6.4 Ω, L=3–4 mH; 3.5 A or more peak provision, continuous current sized from hot holding load"}, {"column0": "Supply", "column1": "36 V if the driver provides **at least 32 V usable bipolar output** under load; verify dropout, phase and heatsinking"}, {"column0": "Inner current loop", "column1": "Identified 50 µs response target for the budget candidate under the hot load; verify phase, ripple and current readback"}, {"column0": "Fast force control", "column1": "10 kHz; P=0.3 A/N and I=20 A/(N·s) for the 20 N/A generic coil; rescale/identify for another Kf"}, {"column0": "Dynamic compensation", "column1": "Measured S acceleration, measured drag/geometry, guide-friction feedforward; lower-load inverse at 1.5 kHz using measured assembled k/c"}, {"column0": "Acquisition", "column1": "ADS131M08, 30 ksample/s per simultaneous channel, 7.68 MHz clock / OSR 128; declared matched 1.9 kHz sensor response, 50 µs EMA and 20 µs pipeline in the tested model; measure the complete installed transfer"}, {"column0": "Acceleration sensors", "column1": "One ADXL354C at ±8 g, two analog axes for the planar prototype; with one M08 about €86.10 including VAT for both chips"}, {"column0": "Position and calibration", "column1": "~1 µm conditioned position noise; use the tighter static targets above, including ±0.01 N force zero and ±0.005 m/s² acceleration bias"}, {"column0": "Robot", "column1": "Identify loaded delay/response, target ±5 ms residuals, retain queued commands and gate new recentering commands"}, {"column0": "Learned control", "column1": "Keep measured-inertia PI + feedforward and guarded robot correction for the prototype; retain the unified minGRU as a reproducible research checkpoint because fresh force and long-travel tests fail"}], "rightAligned": [false, false]}, {"kind": "prose", "id": "report:nested:recommendation:part-2", "value": "The new budget starting point uses the ADXL354C and M08; the public desktop model retains the frozen scientific-reference chain. Earlier M08/fast-acceleration hot-winding tests reached 31.738466 V at a 32 V usable-output limit. Measure actual driver dropout and hot-coil headroom. The new budget baseline passes its finite force tests but does not preserve the preferred 0.05 N reserve. Its full source and replay launcher are retained separately from the public model.\n\n**Final control choice:** retain measured-inertia PI + feedforward. The unified recurrent model was trained, frozen and evaluated; nominal-grid improvement did not generalize to fresh force and sustained-motion tests. The ADXL354C/M08 baseline leaves only **0.007757 N** in its worst fresh long case and exceeds the soft travel band in two long cases. The requested good margin remains a prototype-development target.\n\nA Moticont LVCM-070-051-01-class coil demonstrates plausible force/stroke/electrical values, but it is not a blanket purchase recommendation: its continuous-force curve near stroke ends, hot force constant and cooling must satisfy the required operating region. Budget approximately 1.5 kg total for A in this example, including its 1.24 kg stationary body; its moving coil uses about 0.24 kg of B. Check the robot payload and whole mechanical package. The spring length limit alone does not bound that package.\n\nUse the tighter static-calibration column as the starting acceptance specification, with measured assembled k/c and verified sensor/driver phase. A proposed physical bench criterion is **maximum absolute independent reference-force error plus its applicable measurement uncertainty ≤0.45 N** through the complete loaded test. Prefer a reference with approximately 0.02 N or better applicable uncertainty. This preserves at least 0.05 N against the ±0.5 N requirement if the criterion is achieved; it is a prototype test target, not an already observed hardware pass. Confirm it at operating temperature and with the sanding tool powered.\n\nA larger low-backlash screw servo remains a credible alternative if it supplies at least roughly 0.088 N·m continuous torque at 10 mm/revolution plus reserve, while keeping rotor/screw inertia and friction low. The tested RE25 reference is thermally undersized for continuous 50 N. For the first prototype, choose the coil because it implements the tested force/current path with fewer transmission uncertainties. Validate the complete sensor, drive, guide, spring/damper, mount and robot chain against an independent surface-force reference before claiming ±0.5 N on the powered sanding tool.\n\n**Build the first bench prototype with the guided voice coil, upper rigid link, 19.746 N/mm lower opposed spring pair, 60 N·s/m damper, B–S multi-axis load cell and S–A position sensing. Use one ADXL354C plus one ADS131M08 (about €86 including VAT), synchronized 30 ksample/s acquisition, a measured 50 µs current-response target and 10 kHz measured-inertia PI + feedforward with guarded robot recentering. Retain ±7.5 mm as the no-penalty travel band and stop at physical limits. Keep the neural model for research. This is an affordable prototype starting point: the present cheap-sensor model does not establish a good worst-case margin, so require an independent powered-sanding test at ≤0.45 N error including measurement uncertainty before accepting the system.**"}]}];
const figureAssets={figure0:figure0,figure1:figure1,figure2:figure2,figure3:figure3,figure4:figure4,figure5:figure5,figure6:figure6,figure7:figure7,figure8:figure8,figure9:figure9,figure10:figure10,figure11:figure11,figure12:figure12,figure13:figure13,figure14:figure14,figure15:figure15,figure16:figure16,figure17:figure17,figure18:figure18,figure19:figure19,figure20:figure20,figure21:figure21,figure22:figure22,figure23:figure23,figure24:figure24,figure25:figure25,figure26:figure26,figure27:figure27,figure28:figure28,figure29:figure29,figure30:figure30,figure31:figure31,figure32:figure32,figure33:figure33,figure34:figure34,figure35:figure35,figure36:figure36,figure37:figure37,figure38:figure38,figure39:figure39,figure40:figure40,figure41:figure41};

function Figure({fragment,queries}){const rows=queries[fragment.queryId]?.rows||[];return <DataComponent id={fragment.id} queryId={fragment.queryId} kind="custom" title={fragment.title} sourceRows={rows} displayRows={rows}><figure className="study-figure"><img src={figureAssets[fragment.asset]} alt={fragment.title} loading="eager"/><RichNarrative id={fragment.id+':caption'} value={fragment.caption}/></figure></DataComponent>}
function InlineCell({value}){return String(value).split(/(\*\*[^*]+\*\*|`[^`]+`)/g).map((part,i)=>part.startsWith('**')?<strong key={i}>{part.slice(2,-2)}</strong>:part.startsWith('`')?<code key={i}>{part.slice(1,-1)}</code>:<React.Fragment key={i}>{part}</React.Fragment>)}
function ReportTable({fragment,queries}){const rows=Object.fromEntries(fragment.queryIds.map(id=>[id,queries[id]?.rows||[]]));return <DataComponent id={fragment.id} queryId={fragment.queryIds[0]} queryIds={fragment.queryIds} kind="table" title={fragment.title} sourceRows={rows[fragment.queryIds[0]]} sourceRowsByQuery={rows} displayRows={fragment.rows}><div className="study-table-wrap" data-reviewed-rows><table className="study-table" aria-label={fragment.title}><thead><tr>{fragment.headers.map((h,i)=><th scope="col" key={i} className={fragment.rightAligned[i]?'numeric':''}>{h}</th>)}</tr></thead><tbody>{fragment.rows.map((row,k)=><tr key={k}>{fragment.headers.map((_,i)=><td key={i} className={fragment.rightAligned[i]?'numeric':''}><InlineCell value={row['column'+i]}/></td>)}</tr>)}</tbody></table></div></DataComponent>}
function StudyNode({node,queries,qualificationTable}){const rows=Object.fromEntries(node.queryIds.map(id=>[id,queries[id]?.rows||[]]));const body=<>{node.fragments.map(f=>f.kind==='figure'?<Figure key={f.id} fragment={f} queries={queries}/>:f.kind==='table'?<ReportTable key={f.id} fragment={f} queries={queries}/>:<RichNarrative key={f.id} id={f.id} value={f.value}/>)}{node.title==='Full scientific-reference grid and numerical qualification'?qualificationTable:null}</>;return <section className="study-node" data-depth={node.depth} data-phase={node.title} id={node.id}><div className="study-node-body">{node.queryIds.length?<ReportSection id={node.id+':evidence'} title={node.title} showHeading={false} queryId={node.queryIds[0]} queryIds={node.queryIds} sourceRows={rows[node.queryIds[0]]} sourceRowsByQuery={rows}>{body}</ReportSection>:body}</div>{node.children.map(child=><StudyNode key={child.id} node={child} queries={queries} qualificationTable={qualificationTable}/>)}</section>}
export function ReportContent(){const {snapshot,appTitle}=useDataApp();const [mass,setMass]=useState('all'),[force,setForce]=useState('all');const range=snapshot.queries.qualified_range?.rows||[];const shown=range.filter(r=>(mass==='all'||r.massS_kg===Number(mass))&&(force==='all'||r.reference_N===Number(force)));const c=(field,label)=>({field,label});const n=(field,label)=>({field,label,renderCell:v=>typeof v==='number'?v.toFixed(3):'—'});const table=<DataComponent id="inertial:qualified-case-table" queryId="qualified_range" kind="table" title="Inspect the qualification recordings" sourceRows={range} displayRows={shown}><DataTable rows={shown} caption="Native full-history qualification" toolbarControls={<><label>Tool S <select aria-label="Tool S" value={mass} onChange={e=>setMass(e.target.value)}><option value="all">All masses</option>{[...new Set(range.map(r=>r.massS_kg))].sort((a,b)=>a-b).map(v=><option key={v} value={v}>{v} kg</option>)}</select></label><label>Target <select aria-label="Target force" value={force} onChange={e=>setForce(e.target.value)}><option value="all">All forces</option>{[...new Set(range.map(r=>r.reference_N))].sort((a,b)=>a-b).map(v=><option key={v} value={v}>{v} N</option>)}</select></label></>} columns={[c('massS_kg','S (kg)'),c('reference_N','Target (N)'),c('angle_deg','Angle (°)'),c('mu','Friction'),c('seedRequested','Noise seed'),n('peakNormalForceError_N','Peak error (N)'),n('peakCurrent_A','Current (A)'),n('peakVoltage_V','Voltage (V)'),c('passed','Pass')]}/></DataComponent>;return <article className="report-content" aria-label="Active contact flange nested design study"><header className="report-hero"><h1>{appTitle}</h1></header>{sections.map(node=><StudyNode key={node.id} node={node} queries={snapshot.queries} qualificationTable={table}/>)}</article>}
